    private boolean mockingbirdSpecialReady(MockingbirdSpecialVariant variant) {
        boolean ultimateReady = isUltimateReady();
        return switch (variant) {
            case NEUTRAL -> ultimateReady || (mockingbirdCapturedType == null
                    ? mockingbirdQuestionTimer <= 0
                    : mockingbirdCopiedNeutralActive() && mockingbirdCopiedNeutralReady(mockingbirdCapturedType));
            case SIDE -> ultimateReady || (mockingbirdSideReuseTimer <= 0 && mockingbirdSideFxTimer <= 0);
            case UP -> ultimateReady || (!mockingbirdUpSpecialUsed && mockingbirdUpReuseTimer <= 0 && mockingbirdUpFxTimer <= 0);
            case DOWN -> ultimateReady || mockingbirdLoungeReuseTimer <= 0;
        };
    }

    private boolean mockingbirdCopiedNeutralReady(BirdGame3.BirdType source) {
        if (source == null || source == BirdGame3.BirdType.MOCKINGBIRD) {
            return false;
        }
        boolean ultimateReady = isUltimateReady();
        return switch (source) {
            case PIGEON -> specialCooldown <= 0;
            case EAGLE, FALCON -> raptorCryReuseTimer <= 0;
            case PHOENIX -> specialCooldown <= 0 && phoenixNeutralReuseTimer <= 0 && !phoenixCharging;
            case HUMMINGBIRD -> ultimateReady || hummingNeedleReuseTimer <= 0;
            case TURKEY -> ultimateReady || turkeyGobbleReuseTimer <= 0;
            case ROOSTER -> ultimateReady || (roosterNeutralReuseTimer <= 0 && ownedRoosterChickCount() < ROOSTER_MAX_CHICKS);
            case ROADRUNNER -> ultimateReady || roadrunnerBeepReuseTimer <= 0;
            case PENGUIN -> ultimateReady || penguinBellyReuseTimer <= 0;
            case SHOEBILL -> true;
            case RAZORBILL -> ultimateReady || razorbillStormReuseTimer <= 0;
            case GRINCHHAWK -> true;
            case VULTURE -> ultimateReady || (vultureNeutralReuseTimer <= 0 && vultureCrowTicks > 0 && ownedVultureCrowCount() < 7);
            case OPIUMBIRD, HEISENBIRD -> ultimateReady || opiumNeutralReuseTimer <= 0;
            case TITMOUSE -> ultimateReady || titmouseScoldReuseTimer <= 0;
            case BAT -> ultimateReady || batNeutralReuseTimer <= 0;
            case PELICAN -> ultimateReady || pelicanNeutralReuseTimer <= 0;
            case RAVEN -> ultimateReady || ravenNeutralReuseTimer <= 0;
            case GOOSE -> ultimateReady || gooseHonkReuseTimer <= 0;
            case KIWI -> ultimateReady || kiwiProbeReuseTimer <= 0;
            default -> throw new IllegalStateException("Unexpected value: " + source);
        };
    }

    private boolean mockingbirdCopiedNeutralActive() {
        if (mockingbirdCopiedNeutralSource == null) {
            return true;
        }
        return !switch (mockingbirdCopiedNeutralSource) {
            case PIGEON ->
                    pigeonFeatherBurstTimer > 0 || pigeonRushTimer > 0 || pigeonFlutterTimer > 0 || pigeonScavengeTimer > 0;
            case EAGLE, FALCON -> raptorCryTimer > 0 || raptorRushTimer > 0 || raptorClimbTimer > 0;
            case PHOENIX ->
                    phoenixCharging || phoenixBurstFxTimer > 0 || phoenixFireballTimer > 0 || phoenixSpiralTimer > 0 || phoenixLavaTimer > 0;
            case HUMMINGBIRD -> hummingNeedleHitTimer > 0 || hummingFlashSipTimer > 0 || hummingHoverBurstTimer > 0;
            case TURKEY ->
                    turkeyGobbleCharging || turkeyGobbleTimer > 0 || turkeyStampedeTimer > 0 || turkeyPanicFlapTimer > 0;
            case ROOSTER -> false;
            case ROADRUNNER ->
                    roadrunnerBeepCharging || roadrunnerBeepBurstTimer > 0 || roadrunnerRicochetTimer > 0 || roadrunnerDustDevilTimer > 0;
            case PENGUIN ->
                    penguinBellyCharging || penguinBellySlideTimer > 0 || penguinRocketTimer > 0 || penguinFlopTimer > 0;
            case SHOEBILL ->
                    shoebillStareFxTimer > 0 || shoebillThrustTimer > 0 || shoebillMarshLiftTimer > 0
                            || shoebillStatueTimer > 0 || shoebillCounterBurstTimer > 0 || shoebillFinalStillnessTimer > 0;
            case RAZORBILL -> razorbillStormTimer > 0 || bladeStormFrames > 0 || razorbillShearTimer > 0
                    || razorbillCounterTimer > 0 || razorbillCounterBurstTimer > 0 || razorbillGuillotineTimer > 0;
            case OPIUMBIRD, HEISENBIRD -> leanTimer > 0;
            case TITMOUSE -> titmouseScoldTimer > 0;
            case BAT -> batEchoTimer > 0;
            case PELICAN -> pelicanNeutralTimer > 0;
            case GRINCHHAWK -> grinchHeartSnatchTimer > 0;
            case VULTURE -> vultureCallTimer > 0;
            case RAVEN -> ravenQuillCharging;
            case GOOSE -> gooseHonkTimer > 0;
            case KIWI -> kiwiProbeTimer > 0;
            case MOCKINGBIRD -> false;
        };
    }

    private void refreshMockingbirdCopiedNeutralSource() {
        if (type == BirdGame3.BirdType.MOCKINGBIRD && mockingbirdCopiedNeutralSource != null && mockingbirdCopiedNeutralActive()) {
            mockingbirdCopiedNeutralSource = null;
        }
    }

    boolean hasMockingbirdCapturedType() {
        return mockingbirdCapturedType != null;
    }

