    static int aiReactionFramesForLevel(int cpuLevel) {
        return switch (Math.clamp(cpuLevel, 1, 9)) {
            case 1 -> 26;
            case 2 -> 23;
            case 3 -> 20;
            case 4 -> 16;
            case 5 -> 13;
            case 6 -> 10;
            case 7 -> 7;
            case 8 -> 5;
            default -> 3;
        };
    }

    static int aiOffenseDecisionIntervalForLevel(int cpuLevel) {
        return switch (Math.clamp(cpuLevel, 1, 9)) {
            case 1 -> 18;
            case 2 -> 16;
            case 3 -> 14;
            case 4 -> 12;
            case 5 -> 10;
            case 6 -> 8;
            case 7 -> 7;
            case 8 -> 5;
            default -> 4;
        };
    }

    static int aiSpecialDecisionCooldownFor(BirdGame3.BirdType birdType) {
        if (birdType == BirdGame3.BirdType.PIGEON) {
            return 16;
        }
        return switch (birdType) {
            case EAGLE, SHOEBILL, MOCKINGBIRD, RAZORBILL, OPIUMBIRD, HEISENBIRD, RAVEN, GOOSE -> 20;
            default -> 26;
        };
    }

