    void fireRavenBlackQuillVolley(boolean fan, boolean ultimate) {
        int dir = horizontalInputDirection();
        if (dir == 0) {
            dir = facingDirection();
        }
        facingRight = dir > 0;
        int count = ultimate ? (fan ? 5 : 3) : (fan ? 3 : 1);
        double spread = ultimate ? 0.22 : 0.18;
        double startX = bodyCenterX() + dir * 32.0 * sizeMultiplier;
        double startY = bodyCenterY() - 10.0 * sizeMultiplier;
        for (int i = 0; i < count; i++) {
            double lane = count == 1 ? 0.0 : i - (count - 1) / 2.0;
            double angle = lane * spread;
            double speed = ultimate ? 18.0 : 15.5;
            ravenQuills.add(new RavenQuill(
                    startX,
                    startY + lane * 5.0 * sizeMultiplier,
                    Math.cos(angle) * speed * dir,
                    Math.sin(angle) * speed * dir,
                    ultimate
            ));
        }
        ravenNeutralReuseTimer = ultimate ? 12 : RAVEN_NEUTRAL_REUSE_FRAMES;
        ravenQuillCharging = false;
        ravenQuillChargeFrames = 0;
        ravenQuillChargeUltimate = false;
        attackAnimationTimer = Math.max(attackAnimationTimer, fan ? 14 : 11);
        emitRavenBurst(startX, startY, ultimate ? 28 : 18, ultimate ? Color.GOLD : ravenAccentColor());
        if (ultimate) {
            game.addToKillFeed(shortName() + " loosed the royal Black Quill volley!");
        }
    }

    void specialRavenShadowWarp(boolean ultimate) {
        int dir = horizontalInputDirection();
        if (dir == 0) {
            dir = facingDirection();
        }
        facingRight = dir > 0;

        RavenNode node = bestRavenWarpNode(dir, ultimate ? 780.0 : 560.0);
        boolean empowered = node != null;
        ravenSideStartX = bodyCenterX();
        ravenSideStartY = bodyCenterY();
        if (node != null) {
            consumeRavenNode(node);
            double arrivalOffset = (node.target() != null ? 56.0 : 34.0) * sizeMultiplier;
            double arrivalDir = node.x() >= bodyCenterX() ? -1.0 : 1.0;
            x = clampRavenWarpX(node.x() + arrivalDir * arrivalOffset - 40.0 * sizeMultiplier);
            y = clampRavenWarpY(node.y() - 40.0 * sizeMultiplier);
            facingRight = arrivalDir < 0.0;
        } else {
            x = clampRavenWarpX(x + dir * (ultimate ? 190.0 : 126.0) * sizeMultiplier);
            y = clampRavenWarpY(y - (ultimate ? 14.0 : 8.0) * sizeMultiplier);
        }
        ravenSideEndX = bodyCenterX();
        ravenSideEndY = bodyCenterY();
        ravenSideDirection = facingDirection();
        ravenSideUltimate = ultimate;
        ravenSideEmpowered = empowered;
        ravenSideResolved = false;
        ravenSideTimer = ultimate ? RAVEN_SIDE_FRAMES + 4 : RAVEN_SIDE_FRAMES;
        ravenSideReuseTimer = ultimate ? 16 : RAVEN_SIDE_REUSE_FRAMES;
        Arrays.fill(ravenSideHit, false);
        specialCooldown = 0;
        specialMaxCooldown = 0;
        attackAnimationTimer = Math.max(attackAnimationTimer, ravenSideTimer + 2);
        vx = facingDirection() * (ultimate ? 8.0 : 5.4);
        vy *= 0.18;
        isBlocking = false;
        parryWindowFrames = 0;
        shieldStunFrames = 0;
        emitRavenBurst(ravenSideStartX, ravenSideStartY, empowered ? 28 : 18, ravenShadowColor(false));
        emitRavenBurst(ravenSideEndX, ravenSideEndY, empowered ? 34 : 22, ultimate ? Color.GOLD : ravenAccentColor());
    }

    void specialRavenMurderLift(boolean ultimate) {
        if (ravenLiftUsed && !ultimate) {
            return;
        }
        ravenLiftUsed = true;
        ravenLiftUltimate = ultimate;
        ravenLiftSnapped = false;
        ravenLiftTimer = ultimate ? RAVEN_LIFT_ULTIMATE_FRAMES : RAVEN_LIFT_FRAMES;
        Arrays.fill(ravenLiftHit, false);
        canDoubleJump = true;
        vy = Math.min(vy, ultimate ? -28.0 : -23.0);
        vx *= 0.28;
        attackAnimationTimer = Math.max(attackAnimationTimer, ravenLiftTimer);
        specialCooldown = 0;
        specialMaxCooldown = 0;
        emitRavenBurst(bodyCenterX(), bodyBottomY() - 8.0 * sizeMultiplier,
                ultimate ? 42 : 28, ultimate ? Color.GOLD : ravenAccentColor());
    }

    void specialRavenNevermore(boolean ultimate) {
        specialCooldown = 0;
        specialMaxCooldown = 0;
        if (ravenDecoy != null && ravenDecoy.lifeFrames > 0) {
            double oldCenterX = bodyCenterX();
            double oldCenterY = bodyCenterY();
            x = clampRavenWarpX(ravenDecoy.x - 40.0 * sizeMultiplier);
            y = clampRavenWarpY(ravenDecoy.y - 40.0 * sizeMultiplier);
            ravenDecoy.x = oldCenterX;
            ravenDecoy.y = oldCenterY;
            ravenDecoy.swapped = true;
            ravenDecoy.lifeFrames = Math.min(ravenDecoy.lifeFrames, ultimate ? 150 : 112);
            attackAnimationTimer = Math.max(attackAnimationTimer, 12);
            emitRavenBurst(oldCenterX, oldCenterY, ultimate ? 26 : 18, ravenShadowColor(false));
            emitRavenBurst(bodyCenterX(), bodyCenterY(), ultimate ? 30 : 22, ultimate ? Color.GOLD : ravenAccentColor());
            return;
        }

        ravenDecoy = new RavenDecoy(bodyCenterX(), bodyCenterY(), ultimate);
        ravenDownReuseTimer = ultimate ? 16 : RAVEN_DOWN_REUSE_FRAMES;
        attackAnimationTimer = Math.max(attackAnimationTimer, 12);
        vx *= 0.72;
        emitRavenBurst(ravenDecoy.x, ravenDecoy.y, ultimate ? 30 : 20, ultimate ? Color.GOLD : ravenAccentColor());
    }

    void specialRavenUnkindness() {
        ArrayList<RavenNode> nodes = activeOwnedRavenNodes();
        if (nodes.isEmpty()) {
            addRavenGroundPortent(bodyCenterX() - 110.0 * sizeMultiplier, ravenPortentSurfaceY(bodyCenterX() - 110.0 * sizeMultiplier), true);
            addRavenGroundPortent(bodyCenterX() + 110.0 * sizeMultiplier, ravenPortentSurfaceY(bodyCenterX() + 110.0 * sizeMultiplier), true);
            nodes = activeOwnedRavenNodes();
        }
        if (nodes.size() == 1) {
            nodes.add(new RavenNode(bodyCenterX(), bodyCenterY(), null, null, ++ravenPortentSerialCounter, true));
        }

        ravenUltimateRoutes.clear();
        ravenUltimatePendingRoutes.clear();
        ravenUltimatePortals.clear();
        for (int i = 0; i < nodes.size(); i++) {
            RavenNode start = nodes.get(i);
            RavenNode end = nodes.get((i + 1) % nodes.size());
            ravenUltimatePendingRoutes.add(new RavenUltimateRoute(start.x(), start.y(), end.x(), end.y()));
            ravenUltimatePortals.add(new RavenUltimatePortal(start.x(), start.y(),
                    34.0 + Math.min(18.0, Math.hypot(start.x() - bodyCenterX(), start.y() - bodyCenterY()) * 0.035),
                    i * Math.PI * 0.62));
        }
        Bird latestMarked = latestOwnedRavenMarkedTarget();
        ravenUltimateFinalTargetIndex = latestMarked == null ? -1 : latestMarked.playerIndex;
        ravenUltimateRitualCenterX = bodyCenterX();
        ravenUltimateRitualCenterY = bodyCenterY();
        for (int i = 0; i < 4; i++) {
            double angle = i * Math.PI * 0.5 + Math.PI * 0.25;
            ravenUltimatePortals.add(new RavenUltimatePortal(
                    ravenUltimateRitualCenterX + Math.cos(angle) * (86.0 + i * 16.0) * sizeMultiplier,
                    ravenUltimateRitualCenterY + Math.sin(angle) * (52.0 + i * 9.0) * sizeMultiplier,
                    28.0 + i * 4.0,
                    angle
            ));
        }
        ravenQuillCharging = false;
        ravenQuillChargeFrames = 0;
        ravenQuillChargeUltimate = false;
        ravenNeutralReuseTimer = 14;
        ravenSideReuseTimer = 18;
        ravenDownReuseTimer = 18;
        ravenUltimateWindupTimer = RAVEN_ULTIMATE_WINDUP_FRAMES;
        ravenUltimateTimer = RAVEN_ULTIMATE_WINDUP_FRAMES + RAVEN_ULTIMATE_ROUTE_LIFE_FRAMES;
        ravenUltimateFlockTimer = 0;
        ravenUltimateFlockSpawned = false;
        attackAnimationTimer = Math.max(attackAnimationTimer, RAVEN_ULTIMATE_WINDUP_FRAMES + 18);
        specialCooldown = 0;
        specialMaxCooldown = 0;
        game.addToKillFeed(shortName() + " opened THE UNKINDNESS!");
        game.shakeIntensity = Math.max(game.shakeIntensity, 22);
        game.hitstopFrames = Math.max(game.hitstopFrames, 8);
        emitRavenBurst(bodyCenterX(), bodyCenterY(), 52, Color.web("#B388FF"));
        emitRavenUltimatePortalFeathers(42, true);
    }

    private void resolveRavenUnkindnessMainStrike() {
        if (ravenUltimatePendingRoutes.isEmpty()) {
            ravenUltimateTimer = 0;
            return;
        }
        ravenUltimateRoutes.clear();
        for (RavenUltimateRoute pending : ravenUltimatePendingRoutes) {
            RavenUltimateRoute route = new RavenUltimateRoute(pending.startX, pending.startY, pending.endX, pending.endY);
            ravenUltimateRoutes.add(route);
            applyRavenRouteDamage(route.startX, route.startY, route.endX, route.endY, true);
            emitRavenBurst(route.startX, route.startY, 12, Color.GOLD);
            emitRavenBurst(route.endX, route.endY, 12, Color.web("#B388FF"));
        }
        ravenUltimatePendingRoutes.clear();
        ravenUltimateTimer = RAVEN_ULTIMATE_ROUTE_LIFE_FRAMES;
        ravenUltimateFlockTimer = RAVEN_ULTIMATE_FLOCK_DELAY_FRAMES;

        Bird finalTarget = ravenUltimateFinalTargetIndex >= 0 && ravenUltimateFinalTargetIndex < game.players.length
                ? game.players[ravenUltimateFinalTargetIndex]
                : latestOwnedRavenMarkedTarget();
        if (finalTarget != null && finalTarget.health > 0 && canDamageTarget(finalTarget)) {
            performRavenFinalWarp(finalTarget);
        } else if (!ravenUltimateRoutes.isEmpty()) {
            RavenUltimateRoute last = ravenUltimateRoutes.get(ravenUltimateRoutes.size() - 1);
            x = clampRavenWarpX(last.endX - 40.0 * sizeMultiplier);
            y = clampRavenWarpY(last.endY - 40.0 * sizeMultiplier);
        }

        clearOwnedRavenPortents();
        attackAnimationTimer = Math.max(attackAnimationTimer, RAVEN_ULTIMATE_ROUTE_LIFE_FRAMES);
        game.shakeIntensity = Math.max(game.shakeIntensity, 30);
        game.hitstopFrames = Math.max(game.hitstopFrames, 12);
        emitRavenBurst(bodyCenterX(), bodyCenterY(), 72, Color.GOLD);
        emitRavenUltimatePortalFeathers(36, true);
    }

    private void spawnRavenUltimateVoidFlock() {
        ravenUltimateFlockSpawned = true;
        ravenUltimateFlockTimer = 0;
        boolean crowdedFlock = game.activePlayers >= 8 || game.crowMinions.size() >= 14;
        int count = RAVEN_ULTIMATE_VOID_RAVEN_COUNT + (crowdedFlock ? -1 : 1);
        double centerX = Double.isFinite(ravenUltimateRitualCenterX) && ravenUltimateRitualCenterX != 0.0
                ? ravenUltimateRitualCenterX
                : bodyCenterX();
        double centerY = Double.isFinite(ravenUltimateRitualCenterY) && ravenUltimateRitualCenterY != 0.0
                ? ravenUltimateRitualCenterY
                : bodyCenterY();
        for (int i = 0; i < count; i++) {
            double angle = Math.PI * 2.0 * i / Math.max(1, count);
            double spawnRadius = (82.0 + (i % 3) * 32.0) * sizeMultiplier;
            CrowMinion crow = new CrowMinion(
                    centerX + Math.cos(angle) * spawnRadius,
                    centerY + Math.sin(angle) * spawnRadius * 0.58,
                    null
            ).withVariant(CrowMinion.VARIANT_VOID_RAVEN)
                    .withSpeedMultiplier(1.12)
                    .withOverflowProtectionFrames(420);
            crow.owner = this;
            crow.vx = Math.cos(angle) * (3.8 + SimRng.next() * 1.6);
            crow.vy = Math.sin(angle) * 2.2 - 1.6 - SimRng.next() * 1.8;
            game.crowMinions.add(crow);
            emitRavenBurst(crow.x, crow.y, 10, Color.web("#B388FF"));
        }
        game.addToKillFeed(shortName() + " called void ravens from the portals!");
    }

    private void emitRavenUltimatePortalFeathers(int requestedCount, boolean wide) {
        int count = scaledParticleCount(requestedCount);
        double centerX = ravenUltimateRitualCenterX == 0.0 ? bodyCenterX() : ravenUltimateRitualCenterX;
        double centerY = ravenUltimateRitualCenterY == 0.0 ? bodyCenterY() : ravenUltimateRitualCenterY;
        for (int i = 0; i < count; i++) {
            double angle = game.nextParticleRandom() * Math.PI * 2.0;
            double radius = wide ? 30.0 + game.nextParticleRandom() * 145.0 : 18.0 + game.nextParticleRandom() * 72.0;
            double speed = wide ? 4.0 + game.nextParticleRandom() * 11.0 : 2.0 + game.nextParticleRandom() * 6.0;
            Color color = switch (i % 4) {
                case 0 -> Color.web("#09070F");
                case 1 -> Color.web("#B388FF");
                case 2 -> Color.web("#CFD8DC");
                default -> Color.GOLD;
            };
            game.particles.add(new Particle(
                    centerX + Math.cos(angle) * radius,
                    centerY + Math.sin(angle) * radius * 0.62,
                    Math.cos(angle + Math.PI * 0.5) * speed,
                    Math.sin(angle + Math.PI * 0.5) * speed - 2.8,
                    color.deriveColor(0, 1, 1, 0.82)
            ));
        }
    }

    private void performRavenFinalWarp(Bird target) {
        double startX = bodyCenterX();
        double startY = bodyCenterY();
        double arrivalDir = target.bodyCenterX() >= startX ? -1.0 : 1.0;
        x = clampRavenWarpX(target.bodyCenterX() + arrivalDir * 66.0 * sizeMultiplier - 40.0 * sizeMultiplier);
        y = clampRavenWarpY(target.bodyCenterY() - 40.0 * sizeMultiplier);
        facingRight = arrivalDir < 0.0;
        ravenSideStartX = startX;
        ravenSideStartY = startY;
        ravenSideEndX = bodyCenterX();
        ravenSideEndY = bodyCenterY();
        ravenSideDirection = facingDirection();
        ravenSideUltimate = true;
        ravenSideEmpowered = true;
        ravenSideResolved = false;
        ravenSideTimer = RAVEN_SIDE_FRAMES + 6;
        Arrays.fill(ravenSideHit, false);
    }

    private RavenNode bestRavenWarpNode(int dir, double maxRange) {
        RavenNode best = null;
        double bestScore = Double.MAX_VALUE;
        for (RavenNode node : activeOwnedRavenNodes()) {
            double dx = node.x() - bodyCenterX();
            double dy = node.y() - bodyCenterY();
            double distance = Math.hypot(dx, dy);
            if (distance > maxRange) continue;
            double score = distance + Math.abs(dy) * 0.18;
            if (dx * dir < -28.0) {
                score += 280.0;
            }
            if (score < bestScore) {
                bestScore = score;
                best = node;
            }
        }
        return best;
    }

    private RavenNode nearestRavenSnapNode() {
        RavenNode best = null;
        double bestDist = Double.MAX_VALUE;
        for (RavenNode node : activeOwnedRavenNodes()) {
            double dist = Math.hypot(node.x() - bodyCenterX(), node.y() - bodyCenterY());
            if (dist <= RAVEN_LIFT_SNAP_RADIUS * sizeMultiplier && dist < bestDist) {
                bestDist = dist;
                best = node;
            }
        }
        return best;
    }

    private ArrayList<RavenNode> activeOwnedRavenNodes() {
        ArrayList<RavenNode> nodes = new ArrayList<>();
        for (RavenPortent portent : ravenGroundPortents) {
            nodes.add(new RavenNode(portent.x, portent.y - 18.0 * sizeMultiplier, null, portent, portent.serial, portent.ultimate));
        }
        for (Bird other : game.players) {
            if (other == null || other.health <= 0) continue;
            if (other.ravenPortentOwnerIndex != playerIndex || other.ravenPortentTimer <= 0) continue;
            nodes.add(new RavenNode(other.bodyCenterX(), other.bodyCenterY(), other, null,
                    other.ravenPortentSerial, other.ravenPortentUltimate));
        }
        nodes.sort((a, b) -> Integer.compare(a.serial(), b.serial()));
        return nodes;
    }

    private Bird latestOwnedRavenMarkedTarget() {
        Bird best = null;
        int bestSerial = Integer.MIN_VALUE;
        for (Bird other : game.players) {
            if (other == null || other.health <= 0) continue;
            if (other.ravenPortentOwnerIndex != playerIndex || other.ravenPortentTimer <= 0) continue;
            if (other.ravenPortentSerial > bestSerial) {
                bestSerial = other.ravenPortentSerial;
                best = other;
            }
        }
        return best;
    }

    private void consumeRavenNode(RavenNode node) {
        if (node == null) return;
        if (node.ground() != null) {
            ravenGroundPortents.remove(node.ground());
        }
        if (node.target() != null) {
            clearRavenPortent(node.target());
        }
    }

    boolean hasRavenDecoy() {
        return ravenDecoy != null;
    }

    boolean hasRavenPortentFrom(Bird owner) {
        return owner != null
                && ravenPortentTimer > 0
                && ravenPortentOwnerIndex == owner.playerIndex;
    }

    void clearRavenSpecialObjects() {
        ravenQuills.clear();
        ravenGroundPortents.clear();
        ravenUltimateRoutes.clear();
        ravenUltimatePendingRoutes.clear();
        ravenUltimatePortals.clear();
        ravenDecoy = null;
        clearOwnedRavenPortents();
    }

    private void clearOwnedRavenPortents() {
        ravenGroundPortents.clear();
        for (Bird other : game.players) {
            if (other != null && other.ravenPortentOwnerIndex == playerIndex) {
                clearRavenPortent(other);
            }
        }
    }

    private void applyRavenPortent(Bird target, boolean ultimate) {
        if (target == null || target.health <= 0) {
            return;
        }
        target.ravenPortentOwnerIndex = playerIndex;
        target.ravenPortentUltimate = target.ravenPortentUltimate || ultimate;
        target.ravenPortentTimer = Math.max(target.ravenPortentTimer,
                ultimate ? RAVEN_MARK_ULTIMATE_LIFE_FRAMES : RAVEN_MARK_LIFE_FRAMES);
        target.ravenPortentSerial = ++ravenPortentSerialCounter;
        trimOwnedRavenPortents();
    }

    private void clearRavenPortent(Bird target) {
        if (target == null) {
            return;
        }
        target.ravenPortentTimer = 0;
        target.ravenPortentOwnerIndex = -1;
        target.ravenPortentSerial = 0;
        target.ravenPortentUltimate = false;
    }

    private void addRavenGroundPortent(double x, double y, boolean ultimate) {
        ravenGroundPortents.add(new RavenPortent(
                Math.clamp(x, 12.0, BirdGame3.WORLD_WIDTH - 12.0),
                y,
                ultimate,
                ++ravenPortentSerialCounter
        ));
        trimOwnedRavenPortents();
    }

    private void trimOwnedRavenPortents() {
        while (activeOwnedRavenNodes().size() > RAVEN_MAX_PORTENTS) {
            RavenNode oldest = activeOwnedRavenNodes().get(0);
            consumeRavenNode(oldest);
        }
    }

    private double clampRavenWarpX(double desiredX) {
        return Math.clamp(desiredX, 0.0, BirdGame3.WORLD_WIDTH - 80.0 * sizeMultiplier);
    }

    private double clampRavenWarpY(double desiredY) {
        return Math.clamp(desiredY, 0.0, BirdGame3.GROUND_Y - 80.0 * sizeMultiplier);
    }

    private Color ravenAccentColor() {
        return isVoidHeraldSkin ? Color.web("#B388FF") : Color.web("#90A4AE");
    }

    private Color ravenShadowColor(boolean ultimate) {
        return ultimate ? Color.GOLD : (isVoidHeraldSkin ? Color.web("#4A148C") : Color.web("#10151D"));
    }

    private void emitRavenBurst(double centerX, double centerY, int baseCount, Color color) {
        int particleCount = scaledParticleCount(baseCount);
        for (int i = 0; i < particleCount; i++) {
            double angle = game.nextParticleRandom() * Math.PI * 2.0;
            double speed = 2.0 + game.nextParticleRandom() * 8.0;
            game.particles.add(new Particle(
                    centerX,
                    centerY,
                    Math.cos(angle) * speed,
                    Math.sin(angle) * speed - 2.2,
                    color.deriveColor(0, 1, 1, 0.82)
            ));
        }
    }

    private void clearAIInputs() {
        game.setAiControlKey(playerIndex, leftKey(), false);
        game.setAiControlKey(playerIndex, rightKey(), false);
        game.setAiControlKey(playerIndex, jumpKey(), false);
        game.setAiControlKey(playerIndex, attackKey(), false);
        game.setAiControlKey(playerIndex, specialKey(), false);
        game.setAiControlKey(playerIndex, grabKey(), false);
        game.setAiControlKey(playerIndex, blockKey(), false);
    }

    boolean maintainAIHeldSpecialInputs() {
        if (type == BirdGame3.BirdType.PELICAN && pelicanDownCharging) {
            game.setAiControlKey(playerIndex, specialKey(), true);
            game.setAiControlKey(playerIndex, blockKey(), true);
            return true;
        }
        if (type == BirdGame3.BirdType.RAVEN
                && ravenQuillCharging
                && ravenQuillChargeFrames < RAVEN_QUILL_CHARGE_FAN_FRAMES
                && shouldRavenAIChargeBlackQuill()) {
            game.setAiControlKey(playerIndex, specialKey(), true);
            return true;
        }
        if (type == BirdGame3.BirdType.GOOSE
                && gooseHonkTimer > 0
                && !gooseHonkReleased
                && gooseHonkHoldFrames < GooseSpecials.honkMaxHoldFrames(this)
                && shouldGooseAIChargeHonk()) {
            game.setAiControlKey(playerIndex, specialKey(), true);
            return true;
        }
        if (type == BirdGame3.BirdType.TITMOUSE
                && titmouseStashCharging
                && titmouseSeedStashes.size() >= TITMOUSE_MAX_STASHES) {
            game.setAiControlKey(playerIndex, specialKey(), true);
            game.setAiControlKey(playerIndex, blockKey(), true);
            return true;
        }
        return false;
    }

    boolean shouldRavenAIChargeBlackQuill() {
        Bird target = currentAILockedTarget();
        return target != null
                && combatDistanceTo(target) > 225.0
                && !aiTargetHasActiveThreat(target);
    }

    boolean shouldGooseAIChargeHonk() {
        Bird target = currentAILockedTarget();
        return target != null
                && combatDistanceTo(target) > 225.0
                && !aiTargetHasActiveThreat(target);
    }

    private void resetAIDropCommit() {
        aiDropCommitFrames = 0;
        aiDropCommitDir = 0;
        aiDropOriginY = Double.NaN;
    }

    private Bird currentAILockedTarget() {
        if (aiLockedTargetIndex < 0 || aiLockedTargetIndex >= game.players.length) return null;
        Bird target = game.players[aiLockedTargetIndex];
        if (target == null || target == this || target.health <= 0) return null;
        if (!game.canDamage(this, target)) return null;
        return target;
    }

    private double aiTargetVoidPenalty(Bird candidate) {
        if (!isVoidMap()) return 0.0;
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null) return 0.0;
        double stageLeft = mainStage.x;
        double stageRight = mainStage.x + mainStage.w;
        double centerX = candidate.bodyCenterX();
        double offstageDistance = centerX < stageLeft ? stageLeft - centerX
                : (centerX > stageRight ? centerX - stageRight : 0.0);
        if (offstageDistance <= 0.0) return 0.0;
        double allowance = Math.max(1.0, aiVoidHorizontalAllowance(mainStage));
        double depth = Math.max(0.0, candidate.bodyBottomY() - mainStage.y);
        double penalty = Math.max(0.0, offstageDistance - allowance * 0.22) * 0.22;
        penalty += Math.max(0.0, depth - aiVoidDepthAllowance(mainStage) * 0.45) * 0.07;
        if (aiCanUseAirRecovery()) {
            penalty += offstageDistance * 0.28;
        }
        return penalty;
    }

    private double scoreAITarget(Bird candidate, Bird lockedTarget) {
        double dist = Math.hypot(candidate.x - x, candidate.y - y);
        AIKitProfile own = aiOwnKit();
        AIKitProfile enemy = aiKitProfile(candidate.type);
        double score = 3000.0 / (1.0 + dist);
        score += (100.0 - candidate.health) * 1.8;
        if (candidate.specialCooldown <= 0) score += 40.0;
        if (candidate.playerIndex == 0) score += 15.0;
        if (candidate.attackAnimationTimer > 3 && dist < 260.0) score += 12.0;
        if (candidate.isUltimateReady()) score += 32.0;
        if (aiTargetHasSetupPressure(candidate)) score += 22.0 + own.pressure() * 18.0;
        if (aiTargetHasActiveThreat(candidate)) {
            score += dist < enemy.threatRange() ? 26.0 : 10.0;
            if (aiDurabilityHealth() < 36.0 && dist < aiEnemyThreatRange(candidate)) {
                score -= 38.0;
            }
        }
        if (enemy.recovery() < 0.55 && candidate.bodyBottomY() > bodyBottomY() + 85.0 && own.pressure() > 0.55) {
            score += 18.0;
        }
        if (enemy.zoning() > 0.60 && dist > own.burstRange() * 0.85 && own.pressure() < 0.55) {
            score -= 14.0;
        }
        score += Math.max(0.0, 55.0 - candidate.health) * 0.42;
        score -= Math.abs(candidate.y - y) * (currentFlyUpForce() > 0.0 ? 0.025 : 0.055);
        score -= aiTargetVoidPenalty(candidate);
        if (candidate == lockedTarget) {
            score += 18.0 + Math.min(22.0, aiTargetLockFrames * 0.45);
        }
        return score;
    }

    private Bird pickAITarget() {
        Bird lockedTarget = currentAILockedTarget();
        Bird best = null;
        double bestScore = -Double.MAX_VALUE;
        double lockedScore = -Double.MAX_VALUE;
        for (Bird b : game.players) {
            if (b == null || b == this || b.health <= 0) continue;
            if (!game.canDamage(this, b)) continue;
            double score = scoreAITarget(b, lockedTarget);
            if (b == lockedTarget) {
                lockedScore = score;
            }
            if (score > bestScore) {
                bestScore = score;
                best = b;
            }
        }
        if (lockedTarget != null && lockedScore > -Double.MAX_VALUE / 2.0) {
            double keepMargin = aiTargetLockFrames > 0 ? 18.0 : 8.0;
            if (lockedScore >= bestScore - keepMargin) {
                best = lockedTarget;
            }
        }
        if (best != null) {
            if (lockedTarget == null || best.playerIndex != lockedTarget.playerIndex) {
                aiLockedTargetIndex = best.playerIndex;
                aiTargetLockFrames = 42 + random.nextInt(28);
            } else {
                aiLockedTargetIndex = best.playerIndex;
                aiTargetLockFrames = Math.max(aiTargetLockFrames, 12);
            }
        } else {
            aiLockedTargetIndex = -1;
            aiTargetLockFrames = 0;
        }
        return best;
    }

    private PowerUp pickBestAIPowerUp(Bird target) {
        PowerUp bestPowerUp = null;
        double bestScore = -Double.MAX_VALUE;
        for (PowerUp p : game.powerUps) {
            boolean convenient = isPowerUpConvenient(p, target);
            if (!convenient && !isImmediatePowerUpOpportunity(p)) continue;
            double myDist = Math.hypot(p.x - (x + 40), p.y - (y + 40));
            double score = getScore(target, p, myDist);

            if (score > bestScore) {
                bestScore = score;
                bestPowerUp = p;
            }
        }
        return bestPowerUp;
    }

    private double getScore(Bird target, PowerUp p, double myDist) {
        double score = 0;
        switch (p.type) {
            case HEALTH -> score = (100 - health) * 26 + 140;
            case RAGE -> score = 96;
            case NEON -> score = 95;
            case SPEED -> score = 82;
            case THERMAL -> score = 74;
            case SHRINK -> score = 66;
            case VINE_GRAPPLE -> score = 88;
            case OVERCHARGE -> score = 102;
            case TITAN -> score = 92;
            case BROADSIDE -> score = 90;
        }
        score /= (1 + myDist / 320.0);

        if (target != null) {
            double enemyDist = Math.hypot(p.x - (target.x + 40), p.y - (target.y + 40));
            if (enemyDist < myDist * 0.75) score *= 0.6;
        }
        return score;
    }

    private boolean isImmediatePowerUpOpportunity(PowerUp p) {
        if (p == null) return false;
        double dx = Math.abs(p.x - (x + 40));
        double dy = p.y - (y + 40);
        if (dx < 110 && Math.abs(dy) < 220) return true;
        return dx < 105 && dy > 90 && dy < 360;
    }

    private double rawPowerUpGoalX(PowerUp p) {
        if (p == null) return x;
        double myCx = x + 40;
        double dx = Math.abs(p.x - myCx);
        double dy = p.y - (y + 40);

        if (dy > 90 && dx < 120) {
            Platform standing = findCurrentSupportPlatform();
            if (standing != null) {
                double centerOffset = 25;
                double leftDrop = standing.x - centerOffset - 40 * sizeMultiplier;
                double rightDrop = standing.x + standing.w + centerOffset - 40 * sizeMultiplier;
                leftDrop = Math.clamp(leftDrop, 120.0, BirdGame3.WORLD_WIDTH - 120.0);
                rightDrop = Math.clamp(rightDrop, 120.0, BirdGame3.WORLD_WIDTH - 120.0);
                return Math.abs(leftDrop - p.x) <= Math.abs(rightDrop - p.x) ? leftDrop : rightDrop;
            }
        }
        return p.x;
    }

    private double pickPowerUpGoalX(PowerUp p) {
        return clampGoalXAwayFromVoid(rawPowerUpGoalX(p));
    }

    Platform findCurrentSupportPlatform() {
        double feetX = x + 40 * sizeMultiplier;
        double feetY = y + 80 * sizeMultiplier;
        for (Platform p : game.platforms) {
            boolean isCaveCeiling = game.selectedMap == MapType.CAVE &&
                    p.y <= 1 && p.h >= 60 && p.w >= BirdGame3.WORLD_WIDTH - 10;
            if (isCaveCeiling) continue;
            if (feetX >= p.x && feetX <= p.x + p.w &&
                    Math.abs(feetY - p.y) <= 10 &&
                    y <= p.y + 2) {
                return p;
            }
        }
        return null;
    }

    private PowerUp findBestHealthPowerUp() {
        PowerUp best = null;
        double bestDist = Double.MAX_VALUE;
        for (PowerUp p : game.powerUps) {
            if (p.type != PowerUpType.HEALTH) continue;
            double dist = Math.hypot(p.x - (x + 40), p.y - (y + 40));
            if (dist < bestDist) {
                bestDist = dist;
                best = p;
            }
        }
        return best;
    }

    private boolean shouldPrioritizePowerUp(PowerUp p, Bird target) {
        if (p == null) return false;
        if (!isPowerUpConvenient(p, target)) return false;
        if (isImmediatePowerUpOpportunity(p)) return true;
        if (p.type == PowerUpType.HEALTH && health < 72) return true;
        if (target == null) return true;
        if (target.health < 35 && health > 30) return false;
        double targetDist = Math.hypot(target.x - x, target.y - y);
        return targetDist > aiIdealRangeAgainst(target) * 2.1;
    }

    private boolean isPowerUpConvenient(PowerUp p, Bird target) {
        if (p == null) return false;
        double myCx = x + 40;
        double myCy = y + 40;
        double dx = Math.abs(p.x - myCx);
        double dy = p.y - myCy;
        double dist = Math.hypot(dx, dy);
        double maxDist = health < 25 ? 650 : 480;
        if (dist > maxDist) return false;
        double maxVertical = (currentFlyUpForce() > 0 || !isOnGround()) ? 520 : 320;
        if (Math.abs(dy) > maxVertical) return false;
        if (isVoidMap()) {
            double desiredGoalX = rawPowerUpGoalX(p);
            double safeGoalX = clampGoalXAwayFromVoid(desiredGoalX);
            double edgeDrift = Math.abs(safeGoalX - desiredGoalX);
            Platform mainStage = findAIMainStagePlatform();
            if (mainStage != null) {
                double maxEdgeDrift = Math.max(24.0, aiVoidHorizontalAllowance(mainStage) * 0.55);
                if (edgeDrift > maxEdgeDrift) return false;
                double maxSafePickupY = mainStage.y + aiVoidDepthAllowance(mainStage) * 0.9;
                if (p.y > maxSafePickupY) return false;
            }
        }

        if (target == null) {
            return dx < 260 && Math.abs(dy) < 260;
        }

        double targetDist = Math.hypot(target.x - x, target.y - y);
        double enemyDist = Math.hypot(p.x - (target.x + 40), p.y - (target.y + 40));
        boolean onRoute = dist + enemyDist <= targetDist * 1.25;
        boolean between = dx < Math.abs(target.x - x) + 140;
        boolean nearMe = dist < 260;
        return onRoute || (nearMe && between);
    }

    private boolean isBoundaryPlatform(Platform p) {
        boolean isFloor = p.w >= BirdGame3.WORLD_WIDTH - 10 && p.h >= 200;
        boolean isWall = p.h >= BirdGame3.WORLD_HEIGHT - 10 && p.w <= 150;
        boolean isCaveCeiling = game.selectedMap == MapType.CAVE &&
                p.y <= 1 && p.h >= 60 && p.w >= BirdGame3.WORLD_WIDTH - 10;
        return isFloor || isWall || isCaveCeiling;
    }

    private boolean isVoidMap() {
        return game.selectedMap == MapType.BATTLEFIELD
                || game.selectedMap == MapType.BEACON_CROWN
                || game.selectedMap == MapType.FROSTBITE_FJORD
                || game.selectedMap == MapType.ASHFALL_CATHEDRAL;
    }

    private Platform findAIMainStagePlatform() {
        Platform best = null;
        double bestWidth = -1.0;
        for (Platform p : game.platforms) {
            if (isBoundaryPlatform(p)) continue;
            if (p.w > bestWidth) {
                bestWidth = p.w;
                best = p;
            }
        }
        return best;
    }

    private boolean aiCanUseAirRecovery() {
        return !(currentFlyUpForce() > 0.0) && (type != BirdGame3.BirdType.PIGEON || !canDoubleJump);
    }

    private double topCameraOverflow() {
        return Math.max(0.0, -y);
    }

    private double aiCruiseCeilingY(Platform mainStage) {
        double ceiling = mainStage != null ? mainStage.y - 820.0 : BirdGame3.GROUND_Y - 1000.0;
        ceiling = Math.max(140.0, ceiling);
        return switch (type) {
            case HUMMINGBIRD -> ceiling - 140.0;
            case EAGLE, FALCON, PHOENIX, BAT -> ceiling - 60.0;
            case ROADRUNNER -> roadrunnerSandstormActive() ? ceiling - 40.0 : ceiling;
            default -> ceiling;
        };
    }

    private boolean isAIAboveCruiseCeiling(Bird target, Platform mainStage) {
        if (target == null || currentFlyUpForce() <= 0.0) return false;
        if (y >= aiCruiseCeilingY(mainStage)) return false;
        return target.y > y - 180.0;
    }

    private double aiVoidHorizontalAllowance(Platform mainStage) {
        if (mainStage == null) return 0.0;
        boolean grounded = isOnGround();
        double altitude = Math.max(0.0, mainStage.y - (y + 40 * sizeMultiplier));
        double allowance = 8.0;
        switch (type) {
            case HUMMINGBIRD -> allowance = 360.0 + altitude * 0.18 + Math.max(0.0, -vy) * 10.0;
            case EAGLE, FALCON, PHOENIX, BAT -> allowance = 240.0 + altitude * 0.14 + Math.max(0.0, -vy) * 7.0;
            case TITMOUSE, OPIUMBIRD, HEISENBIRD, RAVEN -> allowance = 210.0 + altitude * 0.12 + Math.max(0.0, -vy) * 6.0;
            case VULTURE -> {
                double launch = grounded ? 0.0 : Math.max(0.0, -vy) * 18.0;
                double altitudeBonus = Math.max(0.0, altitude - 80.0) * 0.16;
                allowance = 40.0 + launch + altitudeBonus + (isFlying ? 55.0 : 0.0);
            }
            case PIGEON -> {
                double fuelRatio = Math.clamp(limitedFlightFuel / LIMITED_FLIGHT_MAX, 0.0, 1.0);
                allowance = 70.0 + fuelRatio * 70.0 + ((grounded || canDoubleJump) ? 35.0 : 0.0) + altitude * 0.06;
            }
            case TURKEY, PELICAN, GRINCHHAWK, ROOSTER, GOOSE -> {
                double fuelRatio = Math.clamp(limitedFlightFuel / LIMITED_FLIGHT_MAX, 0.0, 1.0);
                allowance = 55.0 + fuelRatio * 55.0 + altitude * 0.05;
            }
            case PENGUIN -> allowance = !penguinUpSpecialUsed ? 105.0 + altitude * 0.08 : 10.0;
            case ROADRUNNER -> allowance = roadrunnerSandstormActive()
                    ? 170.0 + altitude * 0.12 + Math.max(0.0, -vy) * 6.0
                    : 50.0 + altitude * 0.04 + Math.max(0.0, -vy) * 2.4;
            case SHOEBILL, MOCKINGBIRD, RAZORBILL -> allowance = 95.0 + altitude * 0.07 + Math.max(0.0, -vy) * 4.0;
        }
        return Math.clamp(allowance, 0.0, Math.max(120.0, mainStage.w * 0.42));
    }

    private double aiVoidDepthAllowance(Platform mainStage) {
        if (mainStage == null) return 80.0;
        boolean grounded = isOnGround();
        double altitude = Math.max(0.0, mainStage.y - (y + 40 * sizeMultiplier));
        double allowance = 60.0 + aiVoidHorizontalAllowance(mainStage) * 0.75;
        switch (type) {
            case HUMMINGBIRD -> allowance += 120.0;
            case VULTURE -> allowance = 85.0
                    + (grounded ? 0.0 : Math.max(0.0, -vy) * 12.0)
                    + Math.max(0.0, altitude - 80.0) * 0.10
                    + (isFlying ? 55.0 : 0.0);
            case PIGEON -> {
                double fuelRatio = Math.clamp(limitedFlightFuel / LIMITED_FLIGHT_MAX, 0.0, 1.0);
                allowance = 140.0 + fuelRatio * 90.0 + ((grounded || canDoubleJump) ? 35.0 : 0.0);
            }
            case TURKEY, PELICAN, GRINCHHAWK, ROOSTER, GOOSE -> {
                double fuelRatio = Math.clamp(limitedFlightFuel / LIMITED_FLIGHT_MAX, 0.0, 1.0);
                allowance = 110.0 + fuelRatio * 70.0;
            }
            case PENGUIN -> allowance = !penguinUpSpecialUsed ? 180.0 + altitude * 0.08 : 70.0;
            case ROADRUNNER -> allowance = roadrunnerSandstormActive()
                    ? 190.0 + Math.max(0.0, altitude - 30.0) * 0.10
                    : 88.0 + Math.max(0.0, altitude - 30.0) * 0.04;
            default -> {
            }
        }
        return Math.clamp(allowance, 60.0, 520.0);
    }

    private double aiVoidReentryInset(Platform mainStage) {
        if (mainStage == null) return 40.0;
        return Math.clamp(aiVoidHorizontalAllowance(mainStage) * 0.22, 18.0, 85.0);
    }

    private double clampGoalXAwayFromVoid(double desiredX) {
        if (!isVoidMap()) return desiredX;
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null) return desiredX;
        double allowance = aiVoidHorizontalAllowance(mainStage);
        double safeLeft = mainStage.x - 40 * sizeMultiplier - allowance;
        double safeRight = mainStage.x + mainStage.w - 40 * sizeMultiplier + allowance;
        double worldLeft = game.battlefieldLeftBound() + 20.0;
        double worldRight = game.battlefieldRightBound() - 80 * sizeMultiplier - 20.0;
        safeLeft = Math.max(worldLeft, safeLeft);
        safeRight = Math.min(worldRight, safeRight);
        return Math.clamp(desiredX, safeLeft, safeRight);
    }

    private boolean isAIDropGoalSafe(double desiredX, double targetY) {
        if (!isVoidMap()) return true;
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null) return true;
        double safeX = clampGoalXAwayFromVoid(desiredX);
        double maxHorizontalError = Math.max(18.0, aiVoidHorizontalAllowance(mainStage) * 0.20);
        if (Math.abs(safeX - desiredX) > maxHorizontalError) return false;
        double maxDropDepth = mainStage.y + aiVoidDepthAllowance(mainStage);
        return targetY <= maxDropDepth;
    }

    private boolean isAIMainlandRecovered(boolean onGround, Platform standing, Platform mainStage) {
        if (mainStage == null) return true;
        if (!onGround) return false;
        return standing == mainStage;
    }

    private boolean shouldAIMaintainRecoveryLock(boolean onGround, Platform standing, Platform mainStage) {
        if (mainStage == null || aiVoidRecoveryLockFrames <= 0) return false;
        return !isAIMainlandRecovered(onGround, standing, mainStage);
    }

    private boolean shouldAIHoldRecoveryJump(Platform mainStage, double recoveryGoalX) {
        if (mainStage == null || aiCanUseAirRecovery()) return false;
        double centerX = x + 40 * sizeMultiplier;
        double bottomY = y + 80 * sizeMultiplier;
        double landingLeft = mainStage.x + aiVoidReentryInset(mainStage) * 0.55;
        double landingRight = mainStage.x + mainStage.w - aiVoidReentryInset(mainStage) * 0.55;
        boolean overLandingLane = centerX >= landingLeft && centerX <= landingRight;
        boolean alignedForLanding = Math.abs(recoveryGoalX - x) < 60.0;
        boolean safelyAboveIsland = bottomY < mainStage.y - 55.0;
        boolean stillBelowLip = bottomY > mainStage.y - 8.0;
        boolean driftingAway = (centerX < mainStage.x && vx < -0.8) || (centerX > mainStage.x + mainStage.w && vx > 0.8);
        if (overLandingLane && alignedForLanding && safelyAboveIsland) {
            return false;
        }
        return !overLandingLane || stillBelowLip || driftingAway;
    }

    private double aiRecoveryGoalX(Platform standing) {
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null) return x;
        double halfWidth = 40 * sizeMultiplier;
        double mainCenterGoalX = mainStage.x + mainStage.w / 2.0 - halfWidth;
        if (standing != null && standing != mainStage && !isBoundaryPlatform(standing)) {
            double platformGoalLeft = standing.x - 28.0 - halfWidth;
            double platformGoalRight = standing.x + standing.w + 28.0 - halfWidth;
            double platformInnerLeft = standing.x + 18.0 - halfWidth;
            double platformInnerRight = standing.x + standing.w - 18.0 - halfWidth;
            if (mainCenterGoalX > platformInnerLeft && mainCenterGoalX < platformInnerRight) {
                return Math.abs(x - platformGoalLeft) <= Math.abs(x - platformGoalRight)
                        ? platformGoalLeft
                        : platformGoalRight;
            }
            return Math.clamp(mainCenterGoalX, platformGoalLeft, platformGoalRight);
        }
        double centerX = x + 40 * sizeMultiplier;
        double safeCenterX = Math.clamp(centerX,
                mainStage.x + aiVoidReentryInset(mainStage),
                mainStage.x + mainStage.w - aiVoidReentryInset(mainStage));
        return safeCenterX - 40 * sizeMultiplier;
    }

    private boolean isAIVoidRecoveryUrgent(boolean onGround, Platform standing) {
        if (!isVoidMap()) return false;
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null) return false;
        if (isAIMainlandRecovered(onGround, standing, mainStage)) return false;
        double centerX = x + 40 * sizeMultiplier;
        double bottomY = y + 80 * sizeMultiplier;
        double hardLeft = mainStage.x - aiVoidHorizontalAllowance(mainStage);
        double hardRight = mainStage.x + mainStage.w + aiVoidHorizontalAllowance(mainStage);
        boolean tooFarOut = centerX < hardLeft || centerX > hardRight;
        boolean deepBelowStage = bottomY > mainStage.y + aiVoidDepthAllowance(mainStage);
        return tooFarOut || deepBelowStage;
    }

    private boolean isAIVoidRecoveryCaution(boolean onGround, Platform standing) {
        if (!isVoidMap()) return false;
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null) return false;
        if (isAIMainlandRecovered(onGround, standing, mainStage)) return false;
        if (onGround && standing != null && standing != mainStage && !isBoundaryPlatform(standing)) {
            return true;
        }
        double centerX = x + 40 * sizeMultiplier;
        double bottomY = y + 80 * sizeMultiplier;
        double stageLeft = mainStage.x;
        double stageRight = mainStage.x + mainStage.w;
        double offstageDistance = centerX < stageLeft ? stageLeft - centerX
                : (centerX > stageRight ? centerX - stageRight : 0.0);
        if (offstageDistance <= 0.0) return false;
        double depth = Math.max(0.0, bottomY - mainStage.y);
        double horizontalRatio = offstageDistance / Math.max(1.0, aiVoidHorizontalAllowance(mainStage));
        double depthRatio = depth / Math.max(1.0, aiVoidDepthAllowance(mainStage));
        boolean movingAway = (centerX < stageLeft && vx < -1.4) || (centerX > stageRight && vx > 1.4);
        return switch (type) {
            case PENGUIN -> depth > 18.0 || horizontalRatio > 0.30 || movingAway || vy > 2.8;
            case PIGEON -> (!canDoubleJump && (depth > 36.0 || horizontalRatio > 0.22 || movingAway))
                    || depthRatio > 0.62
                    || (vy > 3.6 && depth > 22.0);
            case ROADRUNNER -> depth > 30.0
                    || horizontalRatio > 0.48
                    || (movingAway && offstageDistance > 14.0)
                    || (vy > 4.0 && depth > 16.0);
            default -> false;
        };
    }

    private boolean shouldContestTargetFromVoidPlatform(Bird target, boolean onGround, Platform standing, double targetDist) {
        if (!isVoidMap() || target == null || !onGround || standing == null || isBoundaryPlatform(standing)) {
            return false;
        }
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null || standing == mainStage || isAIVoidRecoveryUrgent(onGround, standing)) {
            return false;
        }

        double targetCenterY = target.bodyCenterY();
        double safeFightFloor = mainStage.y + aiVoidDepthAllowance(mainStage) * 0.72;
        if (targetCenterY > safeFightFloor) {
            return false;
        }

        double horizontalGap = Math.abs(target.bodyCenterX() - bodyCenterX());
        double contestDistance = Math.max(340.0, aiIdealRangeAgainst(target) * 1.65);
        return targetDist < contestDistance && horizontalGap < 430.0;
    }

    private boolean aiGoalLeavesMainStage(double goalX) {
        if (!isVoidMap()) return false;
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null) return false;
        double goalCenterX = goalX + 40 * sizeMultiplier;
        return goalCenterX < mainStage.x || goalCenterX > mainStage.x + mainStage.w;
    }

    private boolean shouldAIJumpBeforeOffstage(double goalX) {
        if (!aiGoalLeavesMainStage(goalX)) return false;
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null) return false;
        double centerX = x + 40 * sizeMultiplier;
        double goalCenterX = goalX + 40 * sizeMultiplier;
        double edgeX = goalCenterX < mainStage.x ? mainStage.x : mainStage.x + mainStage.w;
        double distanceToEdge = Math.abs(centerX - edgeX);
        return switch (type) {
            case VULTURE -> distanceToEdge < 140.0;
            case ROADRUNNER -> distanceToEdge < 110.0;
            case PIGEON, TURKEY, PELICAN, GRINCHHAWK, ROOSTER, GOOSE -> distanceToEdge < 95.0;
            default -> false;
        };
    }

    private boolean shouldAIUseRecoverySpecial(boolean onGround, Platform mainStage) {
        if (onGround || mainStage == null) return false;
        if (type != BirdGame3.BirdType.RAZORBILL
                && type != BirdGame3.BirdType.GRINCHHAWK
                && type != BirdGame3.BirdType.BAT
                && type != BirdGame3.BirdType.GOOSE
                && specialCooldown > 0) return false;
        double centerX = x + 40 * sizeMultiplier;
        double bottomY = y + 80 * sizeMultiplier;
        double stageLeft = mainStage.x;
        double stageRight = mainStage.x + mainStage.w;
        boolean offstage = centerX < stageLeft || centerX > stageRight;
        double depth = bottomY - mainStage.y;
        double offstageDistance = centerX < stageLeft ? stageLeft - centerX
                : (centerX > stageRight ? centerX - stageRight : 0.0);
        boolean movingAway = (centerX < stageLeft && vx < -1.2) || (centerX > stageRight && vx > 1.2);
        return switch (type) {
            case PENGUIN -> !penguinUpSpecialUsed
                    && (offstage && (offstageDistance > 14.0 || depth > 10.0 || movingAway || vy > 1.2)
                    || depth > 55.0);
            case PIGEON -> !pigeonUpSpecialUsed
                    && (depth > 82.0
                    || (!canDoubleJump && (depth > 48.0 || (offstage && (offstageDistance > 10.0 || movingAway || vy > 2.2)))));
            case TURKEY -> !turkeyPanicFlapUsed
                    && (depth > 115.0 || (offstage && (offstageDistance > 18.0 || movingAway || vy > 2.4)));
            case ROOSTER -> !roosterUpSpecialUsed
                    && ownedRoosterChickCount() > 0
                    && (depth > 92.0 || (offstage && (offstageDistance > 14.0 || movingAway || vy > 2.0)));
            case ROADRUNNER -> !roadrunnerDustDevilUsed
                    && (depth > 90.0
                    || (offstage && (offstageDistance > 34.0
                    || (movingAway && offstageDistance > 18.0)
                    || (vy > 3.5 && depth > 16.0))));
            case SHOEBILL -> !shoebillUpSpecialUsed
                    && (depth > 96.0 || (offstage && (offstageDistance > 16.0 || movingAway || vy > 2.1)));
            case RAZORBILL -> !razorbillUpSpecialUsed
                    && (depth > 92.0 || (offstage && (offstageDistance > 16.0 || movingAway || vy > 2.0)));
            case GRINCHHAWK -> !grinchUpSpecialUsed
                    && (depth > 108.0 || (offstage && (offstageDistance > 18.0 || movingAway || vy > 2.2)));
            case TITMOUSE -> !titmouseVaultUsed
                    && (depth > 92.0 || (offstage && (offstageDistance > 16.0 || movingAway || vy > 2.0)));
            case BAT -> !batMoonriseUsed
                    && (depth > 88.0 || (offstage && (offstageDistance > 16.0 || movingAway || vy > 2.0)));
            case OPIUMBIRD, HEISENBIRD -> !opiumUpSpecialUsed
                    && (depth > 96.0 || (offstage && (offstageDistance > 16.0 || movingAway || vy > 2.0)));
            case GOOSE -> !gooseLiftUsed
                    && (depth > 105.0 || (offstage && (offstageDistance > 18.0 || movingAway || vy > 2.2)));
            case KIWI -> !kiwiSpringUsed
                    && (depth > 92.0 || (offstage && (offstageDistance > 16.0 || movingAway || vy > 2.0)));
            default -> false;
        };
    }

    private boolean shouldAIUseUtilitySpecial(Bird target, PowerUp powerUp, boolean onGround,
                                              Platform climbPlatform, boolean powerFocus) {
        if (specialCooldown > 0) return false;
        double objectiveX;
        double objectiveY;
        if (powerFocus && powerUp != null) {
            objectiveX = powerUp.x;
            objectiveY = powerUp.y;
        } else if (target != null) {
            objectiveX = target.bodyCenterX();
            objectiveY = target.bodyCenterY();
        } else {
            return false;
        }
        double dx = Math.abs(objectiveX - bodyCenterX());
        double dy = objectiveY - bodyCenterY();
        if (type != BirdGame3.BirdType.PENGUIN) {
            return false;
        }
        if (penguinUpSpecialUsed) {
            return false;
        }
        return onGround
                && dx < 180.0
                && dy < -150.0
                && dy > -540.0
                && (climbPlatform != null || objectiveY < y - 180.0);
    }

    private boolean applyAIVoidRecoveryInputs(boolean onGround, Platform standing) {
        Platform mainStage = findAIMainStagePlatform();
        if (mainStage == null) return false;
        if (isAIMainlandRecovered(onGround, standing, mainStage)) {
            aiVoidRecoveryLockFrames = 0;
            return false;
        }
        boolean urgent = isAIVoidRecoveryUrgent(onGround, standing);
        boolean caution = isAIVoidRecoveryCaution(onGround, standing);
        boolean locked = shouldAIMaintainRecoveryLock(onGround, standing, mainStage);
        if (!urgent && !caution && !locked) return false;
        aiVoidRecoveryLockFrames = Math.max(aiVoidRecoveryLockFrames, urgent ? 40 : 26);
        resetAIDropCommit();
        aiDirectionLock = 0;
        aiStrafeHoldFrames = 0;
        aiStrafeTimer = 0;
        aiMicroPause = 0;
        double recoveryGoalX = aiRecoveryGoalX(standing);
        if (Math.abs(recoveryGoalX - x) > 18) {
            boolean moveLeft = recoveryGoalX < x;
            game.setAiControlKey(playerIndex, moveLeft ? leftKey() : rightKey(), true);
            facingRight = !moveLeft;
        }
        if (!onGround && shouldAIHoldRecoveryJump(mainStage, recoveryGoalX)) {
            game.setAiControlKey(playerIndex, jumpKey(), true);
        }
        if (shouldAIUseRecoverySpecial(onGround, mainStage)) {
            if (type == BirdGame3.BirdType.PIGEON
                    || type == BirdGame3.BirdType.TURKEY
                    || type == BirdGame3.BirdType.ROOSTER
                    || type == BirdGame3.BirdType.ROADRUNNER
                    || type == BirdGame3.BirdType.PENGUIN
                    || type == BirdGame3.BirdType.SHOEBILL
                    || type == BirdGame3.BirdType.RAZORBILL
                    || type == BirdGame3.BirdType.GRINCHHAWK
                    || type == BirdGame3.BirdType.TITMOUSE
                    || type == BirdGame3.BirdType.BAT
                    || type == BirdGame3.BirdType.GOOSE
                    || isOpiumEchoPair()) {
                game.setAiControlKey(playerIndex, jumpKey(), true);
            }
            game.setAiControlKey(playerIndex, specialKey(), true);
        }
        return true;
    }

    private Platform findClimbPlatform(double targetX, double maxRise) {
        Platform best = null;
        double bestScore = -Double.MAX_VALUE;
        double myCx = x + 40;
        double practicalRise = Math.min(maxRise, aiPlatformRiseReach());
        for (Platform p : game.platforms) {
            if (isBoundaryPlatform(p)) continue;
            if (p.y >= y - 40) continue;
            double rise = y - p.y;
            if (rise <= 0 || rise > practicalRise) continue;
            double centerX = p.x + p.w / 2.0;
            double dxTarget = Math.abs(centerX - targetX);
            double dxMe = Math.abs(centerX - myCx);
            double horizontalReach = aiPlatformHorizontalReach(rise);
            if (dxMe > horizontalReach && dxTarget > horizontalReach * 1.25) continue;
            double score = 0;
            double progress = Math.abs(targetX - myCx) - dxTarget;
            score -= rise * 0.95;
            score -= dxTarget * 0.72;
            score -= dxMe * 0.4;
            score += progress * 0.45;
            if ((centerX >= Math.min(myCx, targetX) && centerX <= Math.max(myCx, targetX))) {
                score += 26.0;
            }
            if (rise < practicalRise * 0.65) {
                score += 18.0;
            }
            if (score > bestScore) {
                bestScore = score;
                best = p;
            }
        }
        return best;
    }

    private double aiPlatformRiseReach() {
        double reach = type.jumpHeight * 17.5;
        double flyLift = currentFlyUpForce();
        if (flyLift > 0.0) {
            reach += 90.0 + flyLift * 190.0;
        }
        switch (type) {
            case PIGEON -> {
                if (canDoubleJump) reach += 115.0;
                if (!pigeonUpSpecialUsed) reach += 150.0;
            }
            case PENGUIN -> {
                if (!penguinUpSpecialUsed) reach += 210.0;
            }
            case ROADRUNNER -> {
                if (!roadrunnerDustDevilUsed) reach += 145.0;
            }
            case SHOEBILL -> {
                if (!shoebillUpSpecialUsed) reach += 165.0;
            }
            case RAZORBILL -> {
                if (!razorbillUpSpecialUsed) reach += 160.0;
            }
            case GOOSE -> {
                if (!gooseLiftUsed) reach += 170.0;
                if (limitedFlightFuel > 0.0) reach += 45.0;
            }
            case KIWI -> {
                if (!kiwiSpringUsed) reach += 190.0;
            }
            case OPIUMBIRD, HEISENBIRD -> {
                if (!opiumUpSpecialUsed) reach += 160.0;
            }
            case TITMOUSE, HUMMINGBIRD -> reach += 95.0;
            case BAT -> {
                reach += 95.0;
                if (!batMoonriseUsed) {
                    reach += 150.0;
                }
            }
            case VULTURE -> {
                if (!isOnGround() || isFlying) {
                    reach += 80.0 + Math.max(0.0, -vy) * 12.0;
                }
                if (!vultureUpSpecialUsed) {
                    reach += 145.0;
                }
            }
            case TURKEY, PELICAN, GRINCHHAWK, ROOSTER -> {
                if (limitedFlightFuel > 0.0) reach += 55.0;
            }
            default -> {
            }
        }
        return Math.clamp(reach, 180.0, 760.0);
    }

    private double aiPlatformHorizontalReach(double rise) {
        double reach = 155.0 + type.speed * 82.0;
        if (currentFlyUpForce() > 0.0) {
            reach += 60.0;
        }
        switch (type) {
            case PENGUIN -> {
                if (!penguinUpSpecialUsed) reach += 85.0;
            }
            case ROADRUNNER -> reach += 60.0 + roadrunnerMomentumRatio() * 80.0;
            case SHOEBILL -> {
                if (!shoebillUpSpecialUsed) reach += 38.0;
            }
            case RAZORBILL -> {
                if (!razorbillUpSpecialUsed) reach += 42.0;
            }
            case GOOSE -> {
                reach += 35.0;
                if (!gooseLiftUsed) reach += 44.0;
            }
            case KIWI -> {
                reach += 28.0;
                if (!kiwiSpringUsed) reach += 50.0;
            }
            case OPIUMBIRD, HEISENBIRD -> {
                if (!opiumUpSpecialUsed) reach += 42.0;
            }
            case TITMOUSE, HUMMINGBIRD -> reach += 95.0;
            case BAT -> {
                reach += 95.0;
                if (!batMoonriseUsed) {
                    reach += 42.0;
                }
            }
            case TURKEY, PELICAN, GRINCHHAWK, ROOSTER -> reach += 35.0;
            default -> {
            }
        }
        if (rise < 150.0) {
            reach += 80.0;
        } else if (rise > 320.0) {
            reach -= 35.0;
        }
        return Math.clamp(reach, 160.0, 620.0);
    }

    private double getAIIdealRange() {
        return switch (type) {
            case TURKEY, PELICAN, GRINCHHAWK, GOOSE -> 165;
            case ROADRUNNER -> 182;
            case RAZORBILL, SHOEBILL -> 188;
            case EAGLE, VULTURE, PENGUIN, PHOENIX -> 208;
            case FALCON -> 202;
            case HUMMINGBIRD, TITMOUSE -> 220;
            case OPIUMBIRD, HEISENBIRD, MOCKINGBIRD -> 205;
            case BAT -> 214;
            case PIGEON -> 190;
            case ROOSTER -> 195;
            case RAVEN -> 210;
            case KIWI -> 176;
        };
    }

    private boolean handleAIDodgeBurstThreats(Bird target, boolean onGround) {
        if (target == null) return false;

        boolean dodge = false;
        int dir = target.x > x ? -1 : 1;
        double dx = Math.abs(target.x - x);
        double dy = target.y - y;

        if (target.type == BirdGame3.BirdType.TURKEY
                && (target.isGroundPounding || target.turkeyStampedeTimer > 0 || target.turkeyGobbleCountered)
                && dx < 340 && Math.abs(dy) < 150) dodge = true;
        if (target.type == BirdGame3.BirdType.EAGLE && target.diveTimer > 0 && dx < 430 && dy < 120) dodge = true;
        if (target.type == BirdGame3.BirdType.FALCON && target.diveTimer > 0 && dx < 370 && dy < 120) dodge = true;
        if (target.type == BirdGame3.BirdType.PENGUIN && Math.abs(target.vx) > 14 && dx < 380 && Math.abs(dy) < 110) dodge = true;
        if (target.type == BirdGame3.BirdType.TITMOUSE
                && (target.titmouseBarkskipTimer > 0 || target.titmouseMobbingTimer > 0)
                && dx < 420) dodge = true;
        if (aiTargetHasActiveThreat(target)
                && dx < aiEnemyThreatRange(target) * 0.82
                && Math.abs(dy) < Math.max(120.0, aiKitProfile(target.type).verticalReach() * 0.34)) {
            dodge = true;
        }
        if (target.isUltimateReady()
                && aiKitProfile(target.type).burstRange() > 340.0
                && dx < aiKitProfile(target.type).burstRange() * 0.70
                && Math.abs(dy) < 190.0) {
            dodge = true;
        }

        if (!dodge) {
            aiThreatRecognized = false;
            aiThreatReactionTimer = 0;
            return false;
        }
        if (aiDefenseCooldown > 0) {
            return false;
        }
        int cpuLevel = game.getCpuLevel(playerIndex);
        double skill = Math.clamp((cpuLevel - 1) / 8.0, 0.0, 1.0);
        if (!aiThreatRecognized) {
            aiThreatRecognized = true;
            aiThreatReactionTimer = aiReactionFramesForLevel(cpuLevel) + random.nextInt(4);
            return false;
        }
        if (aiThreatReactionTimer > 0) {
            return false;
        }

        aiThreatRecognized = false;
        aiDefenseCooldown = 16 + random.nextInt(10);
        if (random.nextDouble() > 0.18 + 0.62 * skill) return false;

        if (onGround && random.nextDouble() < 0.42) {
            aiBlockHoldFrames = 7 + random.nextInt(7);
            game.setAiControlKey(playerIndex, blockKey(), true);
            return true;
        }
        if (dir < 0) game.setAiControlKey(playerIndex, leftKey(), true);
        else game.setAiControlKey(playerIndex, rightKey(), true);
        if (onGround && aiJumpCooldown <= 0) {
            game.setAiControlKey(playerIndex, jumpKey(), true);
            aiJumpCooldown = 16;
        }
        return true;
    }

    private double aiSpecialUseChance(double skill, AIKitProfile ownKit, Bird target) {
        if (isNullRockForm()) {
            double bossChance = 0.10 + 0.48 * skill;
            if (isUltimateReady()) {
                bossChance = Math.max(bossChance, 0.72);
            }
            return bossChance;
        }
        double chance = (0.25 + 0.75 * skill)
                * (0.88 + ownKit.pressure() * 0.08 + ownKit.zoning() * 0.08 + ownKit.setup() * 0.10);
        if (target != null && aiTargetHasActiveThreat(target) && ownKit.counter() > 0.30) {
            chance += ownKit.counter() * 0.12;
        }
        if (isUltimateReady()) {
            chance = Math.max(chance, 0.94);
        }
        return Math.clamp(chance, 0.04, 0.98);
    }

    private void clearAISpecialModifierInputs() {
        game.setAiControlKey(playerIndex, leftKey(), false);
        game.setAiControlKey(playerIndex, rightKey(), false);
        game.setAiControlKey(playerIndex, jumpKey(), false);
        game.setAiControlKey(playerIndex, blockKey(), false);
    }

    private void applyAISpecialInput(DirectionalSpecialInput input, int dir) {
        clearAISpecialModifierInputs();
        switch (input) {
            case SIDE -> game.setAiControlKey(playerIndex, dir < 0 ? leftKey() : rightKey(), true);
            case UP -> game.setAiControlKey(playerIndex, jumpKey(), true);
            case DOWN -> game.setAiControlKey(playerIndex, blockKey(), true);
            case NEUTRAL -> {
            }
        }
    }

    private boolean canAIStartSelectedSpecialOrUltimate() {
        if (BirdSpecialReadiness.canStart(this)) {
            return true;
        }
        if (!isUltimateReady()) {
            return false;
        }
        return switch (type) {
            case PIGEON -> canStartPigeonUltimate();
            case EAGLE -> canStartEagleUltimate();
            case FALCON -> canStartFalconUltimate();
            case MOCKINGBIRD -> health > 0 && stunTime <= 0.0 && grabbedBy == null && grabbedTarget == null
                    && !isBlocking && !isDodging();
            default -> false;
        };
    }

    private void configureKitAwareAISpecialInputs(Bird target, double dist, boolean onGround, boolean lowHealth) {
        if (target == null) {
            clearAISpecialModifierInputs();
            return;
        }
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        facingRight = dir > 0;
        applyAISpecialInput(chooseKitAwareAISpecialInput(target, dist, onGround, lowHealth), dir);
    }

    private DirectionalSpecialInput chooseKitAwareAISpecialInput(Bird target, double dist, boolean onGround, boolean lowHealth) {
        double dy = target.bodyCenterY() - bodyCenterY();
        boolean targetAbove = dy < -105.0;
        boolean targetBelow = dy > 95.0;
        boolean enemyActive = aiTargetHasActiveThreat(target);
        boolean targetSettingUp = aiTargetHasSetupPressure(target);
        if (isUltimateReady()) {
            return aiUltimateSpecialInput(target, dist, onGround, lowHealth, targetAbove, targetBelow, enemyActive);
        }

        return switch (type) {
            case PIGEON -> {
                if (!onGround && targetAbove && !pigeonUpSpecialUsed) yield DirectionalSpecialInput.UP;
                if (dist > 88.0 && dist < 315.0 && Math.abs(dy) < 155.0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case EAGLE, FALCON -> {
                if (!onGround && targetBelow && y < target.y - 155.0) yield DirectionalSpecialInput.DOWN;
                if (targetAbove && !raptorUpSpecialUsed) yield DirectionalSpecialInput.UP;
                if (dist > 120.0 && Math.abs(dy) < 155.0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case PHOENIX -> {
                if (!onGround && targetAbove && !phoenixSpiralUsed) yield DirectionalSpecialInput.UP;
                if (dist > 105.0 && dist < 430.0 && phoenixFireballReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                if (Math.abs(target.bodyCenterX() - bodyCenterX()) < 165.0
                        && (targetBelow || dist < 165.0) && phoenixLavaReuseTimer <= 0) yield DirectionalSpecialInput.DOWN;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case HUMMINGBIRD -> {
                if (!onGround && targetAbove && !hummingHoverBurstUsed) yield DirectionalSpecialInput.UP;
                if (onGround && hummingNectarTrapReuseTimer <= 0 && (dist > 165.0 || targetSettingUp)) yield DirectionalSpecialInput.DOWN;
                if (dist < 220.0 && hummingFlashSipReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case TURKEY -> {
                if (!onGround && !turkeyPanicFlapUsed && (targetAbove || y > BirdGame3.GROUND_Y - 190.0)) yield DirectionalSpecialInput.UP;
                if (onGround && enemyActive && dist < 185.0 && turkeyGobbleReuseTimer <= 0) yield DirectionalSpecialInput.NEUTRAL;
                if (onGround && turkeyFeastTrapReuseTimer <= 0 && (dist > 155.0 || lowHealth)) yield DirectionalSpecialInput.DOWN;
                if (dist < 330.0 && Math.abs(dy) < 135.0 && turkeyStampedeReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case ROOSTER -> chooseRoosterAISpecialInput(target, dist, onGround, targetAbove);
            case ROADRUNNER -> {
                if (!onGround && targetAbove && !roadrunnerDustDevilUsed) yield DirectionalSpecialInput.UP;
                if (onGround && roadrunnerPaintedRoadReuseTimer <= 0 && (dist > 170.0 || targetSettingUp)) yield DirectionalSpecialInput.DOWN;
                if (dist > 120.0 && dist < 430.0 && roadrunnerRicochetReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case PENGUIN -> {
                if (!onGround && (targetAbove || isVoidMap()) && !penguinUpSpecialUsed) yield DirectionalSpecialInput.UP;
                if (onGround && penguinSnowFort == null && (lowHealth || enemyActive || dist > 210.0)
                        && penguinSnowFortReuseTimer <= 0) yield DirectionalSpecialInput.DOWN;
                if (dist > 115.0 && dist < 390.0 && Math.abs(dy) < 150.0 && penguinIcebergReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case SHOEBILL -> {
                if (enemyActive && dist < 205.0 && shoebillStatueReuseTimer <= 0) yield DirectionalSpecialInput.DOWN;
                if (!onGround && targetAbove && !shoebillUpSpecialUsed) yield DirectionalSpecialInput.UP;
                if (dist > 145.0 && dist < 340.0 && Math.abs(dy) < 140.0 && shoebillThrustReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case MOCKINGBIRD -> chooseMockingbirdAISpecialInput(target, dist, onGround, lowHealth, targetAbove);
            case RAZORBILL -> {
                if (enemyActive && dist < 215.0 && razorbillCounterReuseTimer <= 0) yield DirectionalSpecialInput.DOWN;
                if (!onGround && targetAbove && !razorbillUpSpecialUsed) yield DirectionalSpecialInput.UP;
                if (dist > 105.0 && dist < 390.0 && Math.abs(dy) < 165.0 && razorbillSideReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case GRINCHHAWK -> {
                if (!onGround && targetAbove && !grinchUpSpecialUsed) yield DirectionalSpecialInput.UP;
                if (dist < 185.0 && grinchHeartSnatchTimer <= 0) yield DirectionalSpecialInput.NEUTRAL;
                if (dist > 105.0 && dist < 380.0 && !grinchSleighActive) yield DirectionalSpecialInput.SIDE;
                if (onGround && grinchPresent == null && (dist > 190.0 || targetSettingUp)) yield DirectionalSpecialInput.DOWN;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case VULTURE -> {
                if (isNullRockForm()) {
                    int cycle = Math.floorMod(nullRockSpecialCycle, 4);
                    if (cycle == 3 && VultureSpecials.ownedNullRockHenchmanCount(this) >= 3) {
                        cycle = 0;
                    }
                    yield switch (cycle) {
                        case 1 -> DirectionalSpecialInput.SIDE;
                        case 2 -> DirectionalSpecialInput.DOWN;
                        case 3 -> DirectionalSpecialInput.UP;
                        default -> DirectionalSpecialInput.NEUTRAL;
                    };
                }
                if (!onGround && targetAbove && !vultureUpSpecialUsed) yield DirectionalSpecialInput.UP;
                if (vultureBait == null && vultureDownReuseTimer <= 0 && (lowHealth || dist > 195.0 || ownedVultureCrowCount() >= 4)) {
                    yield DirectionalSpecialInput.DOWN;
                }
                if (ownedVultureCrowCount() < 7 && vultureCrowTicks > 0 && vultureNeutralReuseTimer <= 0) yield DirectionalSpecialInput.NEUTRAL;
                if (dist < 300.0 && vultureSideReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case OPIUMBIRD -> {
                if (!onGround && targetBelow && !opiumUpSpecialUsed) yield DirectionalSpecialInput.UP;
                if (onGround && opiumDownReuseTimer <= 0 && (opiumResourceMeter < OPIUM_RESOURCE_MAX * 0.42 || dist < 180.0 || targetSettingUp)) {
                    yield DirectionalSpecialInput.DOWN;
                }
                if (dist > 135.0 && dist < 340.0 && opiumSideReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case HEISENBIRD -> chooseHeisenbirdAISpecialInput(
                    dist, onGround, targetBelow, targetSettingUp);
            case TITMOUSE -> chooseTitmouseAISpecialInput(target, dist, onGround, targetAbove, targetSettingUp);
            case BAT -> {
                if (!onGround && targetAbove && !batMoonriseUsed) yield DirectionalSpecialInput.UP;
                if (!onGround && targetBelow && batSilentReuseTimer <= 0) yield DirectionalSpecialInput.DOWN;
                if (dist > 130.0 && dist < 330.0 && batWingcutReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case PELICAN -> choosePelicanAISpecialInput(target, dist, onGround, targetAbove, targetBelow, enemyActive);
            case RAVEN -> {
                boolean targetMarked = target.ravenPortentOwnerIndex == playerIndex && target.ravenPortentTimer > 0;
                if (!onGround && targetAbove && !ravenLiftUsed) yield DirectionalSpecialInput.UP;
                if (onGround && ravenDecoy == null && (enemyActive || lowHealth) && ravenDownReuseTimer <= 0) yield DirectionalSpecialInput.DOWN;
                if (!activeOwnedRavenNodes().isEmpty() && dist > 125.0 && ravenSideReuseTimer <= 0
                        && (targetMarked || dist > 230.0)) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case GOOSE -> {
                if (!onGround && targetAbove && !gooseLiftUsed) yield DirectionalSpecialInput.UP;
                if (onGround && (enemyActive || lowGooseTerritory() || gooseNest == null)
                        && gooseNestReuseTimer <= 0) yield DirectionalSpecialInput.DOWN;
                if (dist > 108.0 && dist < 370.0 && gooseBargeReuseTimer <= 0) yield DirectionalSpecialInput.SIDE;
                yield DirectionalSpecialInput.NEUTRAL;
            }
            case KIWI -> chooseKiwiAISpecialInput(
                    target, dist, onGround, targetAbove, targetBelow, enemyActive);
        };
    }

    DirectionalSpecialInput chooseKiwiAISpecialInput(Bird target, double dist, boolean onGround,
                                                      boolean targetAbove, boolean targetBelow,
                                                      boolean enemyActive) {
        double dy = target.bodyCenterY() - bodyCenterY();
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        if (!onGround && targetAbove && !kiwiSpringUsed) {
            return DirectionalSpecialInput.UP;
        }
        if (!onGround && targetBelow && kiwiStompReuseTimer <= 0 && canKiwiAIStompSafely()) {
            return DirectionalSpecialInput.DOWN;
        }
        if (onGround && enemyActive && dist < 150.0 && kiwiStompReuseTimer <= 0) {
            return DirectionalSpecialInput.DOWN;
        }
        if (dist > 95.0 && dist < 340.0 && Math.abs(dy) < 145.0
                && kiwiBurrowReuseTimer <= 0 && canKiwiAIBurrowSafely(dir)) {
            return DirectionalSpecialInput.SIDE;
        }
        return DirectionalSpecialInput.NEUTRAL;
    }

    private boolean canKiwiAIStompSafely() {
        double projectedCenterX = bodyCenterX() + vx * 2.0;
        return hasKiwiAILandingLane(projectedCenterX);
    }

    private boolean canKiwiAIBurrowSafely(int dir) {
        double projectedCenterX = bodyCenterX()
                + Integer.signum(dir) * 13.2 * KIWI_BURROW_FRAMES;
        return hasKiwiAILandingLane(projectedCenterX);
    }

    private boolean hasKiwiAILandingLane(double centerX) {
        if (!isVoidMap()) {
            return true;
        }
        double minimumLandingY = bodyBottomY() - 12.0 * sizeMultiplier;
        for (Platform platform : game.platforms) {
            if (isBoundaryPlatform(platform)) continue;
            double edgeInset = Math.min(24.0 * sizeMultiplier, platform.w * 0.18);
            if (centerX < platform.x + edgeInset || centerX > platform.x + platform.w - edgeInset) continue;
            if (platform.y >= minimumLandingY) {
                return true;
            }
        }
        return false;
    }

    DirectionalSpecialInput choosePelicanAISpecialInput(Bird target, double dist, boolean onGround,
                                                        boolean targetAbove, boolean targetBelow,
                                                        boolean enemyActive) {
        double dy = target.bodyCenterY() - bodyCenterY();
        double horizontalGap = Math.abs(target.bodyCenterX() - bodyCenterX());
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        if (!onGround && targetAbove && !pelicanUpSpecialUsed && canPelicanAIKeelDiveSafely()) {
            return DirectionalSpecialInput.UP;
        }
        if (pelicanCargoCount <= 0) {
            if (onGround && dist > 255.0 && dist < 560.0 && !enemyActive && pelicanDownReuseTimer <= 0) {
                return DirectionalSpecialInput.DOWN;
            }
            if (dist < 188.0 && Math.abs(dy) < 130.0 && pelicanNeutralReuseTimer <= 0) {
                return DirectionalSpecialInput.NEUTRAL;
            }
            if (dist > 120.0 && dist < 390.0 && Math.abs(dy) < 190.0
                    && pelicanSideReuseTimer <= 0 && canPelicanAIBreakwaterSafely(dir)) {
                return DirectionalSpecialInput.SIDE;
            }
            return DirectionalSpecialInput.NEUTRAL;
        }
        if (!onGround && targetBelow && horizontalGap < 230.0 && pelicanDownReuseTimer <= 0) {
            return DirectionalSpecialInput.DOWN;
        }
        if (dist > 108.0 && dist < 415.0 && Math.abs(dy) < 200.0
                && pelicanSideReuseTimer <= 0 && canPelicanAIBreakwaterSafely(dir)) {
            return DirectionalSpecialInput.SIDE;
        }
        if ((horizontalGap < 260.0 || enemyActive) && Math.abs(dy) < 175.0 && pelicanDownReuseTimer <= 0) {
            return DirectionalSpecialInput.DOWN;
        }
        return DirectionalSpecialInput.NEUTRAL;
    }

    private boolean canPelicanAIKeelDiveSafely() {
        double projectedCenterX = bodyCenterX() + vx * 8.0;
        return hasPelicanAILandingLane(projectedCenterX);
    }

    private boolean canPelicanAIBreakwaterSafely(int dir) {
        int effectiveCargo = pelicanEffectiveCargo();
        boolean empowered = pelicanFullHoldActive();
        int activeFrames = empowered ? PELICAN_SIDE_FRAMES + 5 : PELICAN_SIDE_FRAMES;
        double speed = 11.8 + effectiveCargo * 2.8 + (empowered ? 2.8 : 0.0);
        double projectedCenterX = bodyCenterX() + Integer.signum(dir) * speed * activeFrames;
        return hasPelicanAILandingLane(projectedCenterX);
    }

    private boolean hasPelicanAILandingLane(double centerX) {
        if (!isVoidMap()) {
            return true;
        }
        double minimumLandingY = bodyBottomY() - 12.0 * sizeMultiplier;
        for (Platform platform : game.platforms) {
            if (isBoundaryPlatform(platform)) continue;
            double edgeInset = Math.min(24.0 * sizeMultiplier, platform.w * 0.18);
            if (centerX < platform.x + edgeInset || centerX > platform.x + platform.w - edgeInset) continue;
            if (platform.y >= minimumLandingY) {
                return true;
            }
        }
        return false;
    }

    DirectionalSpecialInput chooseMockingbirdAISpecialInput(Bird target, double dist, boolean onGround,
                                                            boolean lowHealth, boolean targetAbove) {
        if (!onGround && targetAbove && !mockingbirdUpSpecialUsed) {
            return DirectionalSpecialInput.UP;
        }
        if (onGround && mockingbirdLoungeReuseTimer <= 0 && (!loungeActive || lowHealth)) {
            return DirectionalSpecialInput.DOWN;
        }
        if (onGround && mockingbirdLoungeReuseTimer <= 0
                && mockingbirdCapturedType == null && target != null
                && dist < 145.0 && !isInsideMockingbirdLounge(target)) {
            return DirectionalSpecialInput.DOWN;
        }
        if (mockingbirdCapturedType != null
                && mockingbirdSpecialReady(MockingbirdSpecialVariant.NEUTRAL)) {
            return DirectionalSpecialInput.NEUTRAL;
        }
        if (target != null
                && dist > 60.0 && dist < 275.0
                && Math.abs(target.bodyCenterY() - bodyCenterY()) < 135.0) {
            return DirectionalSpecialInput.SIDE;
        }

        // An empty neutral is only a question-mark tell. Selecting SIDE while
        // Mimic Call is unavailable lets the readiness gate decline the action
        // instead of making the CPU repeatedly spend offense decisions on a no-op.
        return mockingbirdCapturedType == null
                ? DirectionalSpecialInput.SIDE
                : DirectionalSpecialInput.NEUTRAL;
    }

    DirectionalSpecialInput chooseRoosterAISpecialInput(Bird target, double dist, boolean onGround,
                                                        boolean targetAbove) {
        int owned = ownedRoosterChickCount();
        if (!onGround && targetAbove && !roosterUpSpecialUsed && owned > 0) {
            return DirectionalSpecialInput.UP;
        }
        if (owned < ROOSTER_MAX_CHICKS && roosterNeutralReuseTimer <= 0) {
            return DirectionalSpecialInput.NEUTRAL;
        }
        if (nextRoosterFollowerChick() != null && dist < 470.0 && roosterSideReuseTimer <= 0) {
            return DirectionalSpecialInput.SIDE;
        }
        if (roosterDownReuseTimer <= 0 && shouldRoosterAIRecallChicks(target)) {
            return DirectionalSpecialInput.DOWN;
        }
        return DirectionalSpecialInput.NEUTRAL;
    }

    private boolean shouldRoosterAIRecallChicks(Bird target) {
        if (target == null || nextRoosterFollowerChick() != null) {
            return false;
        }
        boolean hasDeployedChick = false;
        double targetX = target.bodyCenterX();
        double targetY = target.bodyCenterY();
        for (ChickMinion chick : ownedRoosterChicks()) {
            if (chick.roosterSwarm || chick.followingOwner) {
                continue;
            }
            hasDeployedChick = true;
            double dx = targetX - (chick.x + chick.width * 0.5);
            double dy = targetY - (chick.y + chick.height * 0.5);
            if (dx * dx + dy * dy < 520.0 * 520.0) {
                return false;
            }
        }
        return hasDeployedChick;
    }

    boolean shouldRoosterAIUseSpecial(Bird target, double dist, boolean lowHealth, double dy) {
        int owned = ownedRoosterChickCount();
        boolean hasFollower = nextRoosterFollowerChick() != null;
        boolean needsRecall = owned > 0
                && !hasFollower
                && roosterDownReuseTimer <= 0
                && shouldRoosterAIRecallChicks(target);
        return (owned < ROOSTER_MAX_CHICKS && (dist < 500.0 || lowHealth))
                || (hasFollower && dist < 460.0 && Math.abs(dy) < 210.0)
                || needsRecall;
    }

    DirectionalSpecialInput chooseTitmouseAISpecialInput(Bird target, double dist, boolean onGround,
                                                         boolean targetAbove, boolean targetSettingUp) {
        if (!onGround && targetAbove && !titmouseVaultUsed) {
            return DirectionalSpecialInput.UP;
        }
        if (onGround && titmouseStashReuseTimer <= 0 && shouldTitmouseAIDetonateSeedStashes(target)) {
            return DirectionalSpecialInput.DOWN;
        }
        if (onGround && titmouseSeedStashes.size() < TITMOUSE_MAX_STASHES
                && (dist > 145.0 || targetSettingUp) && titmouseStashReuseTimer <= 0) {
            return DirectionalSpecialInput.DOWN;
        }
        if (!titmouseSeedStashes.isEmpty()
                && (target.isTitmouseMarkedBy(this) || dist > 170.0)) {
            return DirectionalSpecialInput.SIDE;
        }
        return DirectionalSpecialInput.NEUTRAL;
    }

    DirectionalSpecialInput chooseHeisenbirdAISpecialInput(double dist, boolean onGround,
                                                            boolean targetBelow, boolean targetSettingUp) {
        if (!onGround && targetBelow && !opiumUpSpecialUsed) {
            return DirectionalSpecialInput.UP;
        }

        if (onGround && opiumDownReuseTimer <= 0
                && (opiumResourceMeter < OPIUM_RESOURCE_MAX * 0.42
                || dist < 180.0
                || targetSettingUp)) {
            return DirectionalSpecialInput.DOWN;
        }
        if (dist > 135.0 && dist < 340.0
                && opiumSideReuseTimer <= 0
                && opiumResourceMeter >= HEISEN_SIDE_RESOURCE_COST) {
            return DirectionalSpecialInput.SIDE;
        }
        if (opiumResourceMeter < HEISEN_NEUTRAL_RESOURCE_COST) {
            // Selecting the cooling-down node makes the readiness gate wait
            // instead of converting a nearly empty meter into a fueled move.
            return DirectionalSpecialInput.DOWN;
        }
        return DirectionalSpecialInput.NEUTRAL;
    }

    private boolean shouldTitmouseAIDetonateSeedStashes(Bird target) {
        if (target == null || titmouseSeedStashes.size() < TITMOUSE_MAX_STASHES) {
            return false;
        }
        for (TitmouseSeedStash stash : titmouseSeedStashes) {
            double radius = (stash.ultimate ? 112.0 : 92.0) * sizeMultiplier;
            double dx = target.bodyCenterX() - stash.x;
            double dy = target.bodyCenterY() - (stash.y - 18.0 * sizeMultiplier);
            if (Math.hypot(dx, dy) <= radius + target.combatRadius()) {
                return true;
            }
        }
        return false;
    }

    boolean shouldTitmouseAIUseSpecial(Bird target, double dist, boolean onGround, boolean enemySetup) {
        return (dist > 125.0 && dist < 590.0)
                || (onGround && titmouseSeedStashes.size() < TITMOUSE_MAX_STASHES
                && (dist > 135.0 || enemySetup))
                || (onGround && shouldTitmouseAIDetonateSeedStashes(target));
    }

    private DirectionalSpecialInput aiUltimateSpecialInput(Bird target, double dist, boolean onGround, boolean lowHealth,
                                                          boolean targetAbove, boolean targetBelow, boolean enemyActive) {
        return switch (type) {
            case PENGUIN -> onGround ? DirectionalSpecialInput.DOWN : DirectionalSpecialInput.UP;
            case SHOEBILL -> DirectionalSpecialInput.DOWN;
            case RAZORBILL -> enemyActive && dist < 220.0 ? DirectionalSpecialInput.DOWN : DirectionalSpecialInput.NEUTRAL;
            case TURKEY -> onGround && dist < 340.0 ? DirectionalSpecialInput.SIDE : DirectionalSpecialInput.DOWN;
            case ROADRUNNER -> DirectionalSpecialInput.NEUTRAL;
            case GRINCHHAWK -> DirectionalSpecialInput.DOWN;
            case PELICAN -> pelicanCargoCount > 0 ? DirectionalSpecialInput.DOWN : DirectionalSpecialInput.NEUTRAL;
            case VULTURE -> DirectionalSpecialInput.NEUTRAL;
            case ROOSTER -> DirectionalSpecialInput.NEUTRAL;
            case RAVEN -> !activeOwnedRavenNodes().isEmpty() ? DirectionalSpecialInput.SIDE : DirectionalSpecialInput.NEUTRAL;
            case GOOSE -> lowHealth || enemyActive ? DirectionalSpecialInput.DOWN : DirectionalSpecialInput.NEUTRAL;
            case PHOENIX -> targetBelow && dist < 280.0 ? DirectionalSpecialInput.DOWN : DirectionalSpecialInput.NEUTRAL;
            case HUMMINGBIRD -> dist < 260.0 ? DirectionalSpecialInput.SIDE : DirectionalSpecialInput.NEUTRAL;
            case BAT -> targetAbove ? DirectionalSpecialInput.UP : DirectionalSpecialInput.NEUTRAL;
            case TITMOUSE -> DirectionalSpecialInput.DOWN;
            case OPIUMBIRD, HEISENBIRD -> DirectionalSpecialInput.DOWN;
            case MOCKINGBIRD -> DirectionalSpecialInput.DOWN;
            case EAGLE, FALCON, PIGEON -> DirectionalSpecialInput.NEUTRAL;
            case KIWI -> DirectionalSpecialInput.NEUTRAL;
        };
    }

    private void configureShoebillAISpecialInputs(Bird target, double dist, boolean onGround) {
        if (target == null || type != BirdGame3.BirdType.SHOEBILL) {
            return;
        }
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        facingRight = dir > 0;
        boolean targetAttacking = target.attackAnimationTimer > 2 || target.grabThrowLockTimer > 0;
        if (onGround && targetAttacking && dist < 185.0 && shoebillStatueReuseTimer <= 0) {
            game.setAiControlKey(playerIndex, blockKey(), true);
            return;
        }
        if (dist > 155.0 && dist < 330.0 && shoebillThrustReuseTimer <= 0) {
            game.setAiControlKey(playerIndex, dir < 0 ? leftKey() : rightKey(), true);
        }
    }

    private void configureRazorbillAISpecialInputs(Bird target, double dist, boolean onGround) {
        if (target == null || type != BirdGame3.BirdType.RAZORBILL) {
            return;
        }
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        facingRight = dir > 0;
        double dy = target.bodyCenterY() - bodyCenterY();
        boolean targetAttacking = target.attackAnimationTimer > 2
                || target.bladeStormFrames > 0
                || target.diveTimer > 0
                || target.isZipping;
        if (targetAttacking && dist < 205.0 && razorbillCounterReuseTimer <= 0) {
            game.setAiControlKey(playerIndex, blockKey(), true);
            return;
        }
        if (dy < -120.0 && dist < 360.0 && !razorbillUpSpecialUsed) {
            game.setAiControlKey(playerIndex, jumpKey(), true);
            return;
        }
        if (dist > 105.0 && dist < 380.0 && razorbillSideReuseTimer <= 0) {
            game.setAiControlKey(playerIndex, dir < 0 ? leftKey() : rightKey(), true);
        }
    }

    private void configureTitmouseAISpecialInputs(Bird target, double dist, boolean onGround) {
        if (target == null || type != BirdGame3.BirdType.TITMOUSE) {
            return;
        }
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        facingRight = dir > 0;
        double dy = target.bodyCenterY() - bodyCenterY();
        if (!onGround && dy < -110.0 && !titmouseVaultUsed) {
            game.setAiControlKey(playerIndex, jumpKey(), true);
            return;
        }
        if (onGround && titmouseSeedStashes.isEmpty() && dist > 150.0) {
            game.setAiControlKey(playerIndex, blockKey(), true);
            return;
        }
        if (!titmouseSeedStashes.isEmpty() && (target.isTitmouseMarkedBy(this) || dist > 170.0)) {
            game.setAiControlKey(playerIndex, dir < 0 ? leftKey() : rightKey(), true);
        }
    }

    private void configureBatAISpecialInputs(Bird target, double dist, boolean onGround) {
        if (target == null || type != BirdGame3.BirdType.BAT) {
            return;
        }
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        facingRight = dir > 0;
        double dy = target.bodyCenterY() - bodyCenterY();
        if (!onGround && dy < -115.0 && !batMoonriseUsed) {
            game.setAiControlKey(playerIndex, jumpKey(), true);
            return;
        }
        if (!onGround && dy > 76.0 && batSilentReuseTimer <= 0 && random.nextDouble() < 0.50) {
            game.setAiControlKey(playerIndex, blockKey(), true);
            return;
        }
        if (dist > 130.0 && dist < 320.0 && batWingcutReuseTimer <= 0 && random.nextDouble() < 0.62) {
            game.setAiControlKey(playerIndex, dir < 0 ? leftKey() : rightKey(), true);
        }
    }

    private void configureRavenAISpecialInputs(Bird target, double dist, boolean onGround) {
        if (target == null || type != BirdGame3.BirdType.RAVEN) {
            return;
        }
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        facingRight = dir > 0;
        double dy = target.bodyCenterY() - bodyCenterY();
        boolean targetMarked = target.ravenPortentOwnerIndex == playerIndex && target.ravenPortentTimer > 0;
        boolean hasNode = !activeOwnedRavenNodes().isEmpty();

        if (!onGround && dy < -92.0 && !ravenLiftUsed) {
            game.setAiControlKey(playerIndex, jumpKey(), true);
            return;
        }
        if (hasNode && dist > 132.0 && dist < 520.0 && ravenSideReuseTimer <= 0
                && (targetMarked || random.nextDouble() < 0.72)) {
            game.setAiControlKey(playerIndex, dir < 0 ? leftKey() : rightKey(), true);
            return;
        }
        if (onGround && ravenDecoy == null && ravenDownReuseTimer <= 0
                && (dist < 150.0 || target.attackAnimationTimer > 2) && random.nextDouble() < 0.58) {
            game.setAiControlKey(playerIndex, blockKey(), true);
            return;
        }
        if (ravenDecoy != null && dist > 230.0 && random.nextDouble() < 0.42) {
            game.setAiControlKey(playerIndex, blockKey(), true);
        }
    }

    private void configureGooseAISpecialInputs(Bird target, double dist, boolean onGround) {
        if (target == null || type != BirdGame3.BirdType.GOOSE) {
            return;
        }
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        facingRight = dir > 0;
        double dy = target.bodyCenterY() - bodyCenterY();
        boolean targetAttacking = target.attackAnimationTimer > 2
                || target.gooseBargeTimer > 0
                || target.diveTimer > 0
                || target.bladeStormFrames > 0;
        if (!onGround && dy < -96.0 && !gooseLiftUsed) {
            game.setAiControlKey(playerIndex, jumpKey(), true);
            return;
        }
        if (onGround && targetAttacking && dist < 210.0 && gooseNestReuseTimer <= 0) {
            game.setAiControlKey(playerIndex, blockKey(), true);
            return;
        }
        if (onGround && (gooseNest == null || gooseNest.lifeFrames <= 0)
                && (lowGooseTerritory() || dist > 160.0) && gooseNestReuseTimer <= 0
                && random.nextDouble() < 0.42) {
            game.setAiControlKey(playerIndex, blockKey(), true);
            return;
        }
        if (dist > 108.0 && dist < 360.0 && gooseBargeReuseTimer <= 0 && random.nextDouble() < 0.68) {
            game.setAiControlKey(playerIndex, dir < 0 ? leftKey() : rightKey(), true);
        }
    }

    private boolean lowGooseTerritory() {
        return gooseTerritoryMeter < GOOSE_TERRITORY_MAX * 0.45;
    }

    private void configureOpiumAISpecialInputs(Bird target, double dist, boolean onGround) {
        if (target == null || !isOpiumEchoPair()) {
            return;
        }
        int dir = target.bodyCenterX() >= bodyCenterX() ? 1 : -1;
        facingRight = dir > 0;
        double dy = target.bodyCenterY() - bodyCenterY();
        if (!onGround && dy > 95.0 && !opiumUpSpecialUsed) {
            game.setAiControlKey(playerIndex, jumpKey(), true);
            return;
        }
        if (onGround && opiumResourceMeter < OPIUM_RESOURCE_MAX * 0.34 && opiumDownReuseTimer <= 0) {
            game.setAiControlKey(playerIndex, blockKey(), true);
            return;
        }
        if (onGround && dist < 180.0 && opiumDownReuseTimer <= 0 && random.nextDouble() < 0.42) {
            game.setAiControlKey(playerIndex, blockKey(), true);
            return;
        }
        if (dist > 138.0 && dist < 320.0 && opiumSideReuseTimer <= 0) {
            game.setAiControlKey(playerIndex, dir < 0 ? leftKey() : rightKey(), true);
        }
    }

    private boolean shouldUseSpecialAI(Bird target, double dist, boolean onGround, boolean lowHealth) {
        double dy = target.y - y;
        if (isUltimateReady()) {
            return true;
        }
        AIKitProfile own = aiOwnKit();
        boolean enemyActive = aiTargetHasActiveThreat(target);
        boolean enemySetup = aiTargetHasSetupPressure(target);
        boolean targetVulnerable = target.aiDurabilityHealth() < 42.0 || target.stunTime > 0.0 || target.knockdownTimer > 0;
        double ideal = aiIdealRangeAgainst(target);
        switch (type) {
            case PIGEON:
                return targetVulnerable
                        || (dist > 85 && dist < 315 && Math.abs(dy) < 155);
            case EAGLE:
                return (y < BirdGame3.GROUND_Y - 760 && dy > 150 && dist < 540)
                        || (dist > 135 && dist < 430 && Math.abs(dy) < 160)
                        || enemySetup;
            case FALCON:
                return dist < 390 && dy > -145 && (onGround || lowHealth || target.health > health + 8 || targetVulnerable);
            case PHOENIX:
                return dist < 430 && (lowHealth || Math.abs(dy) < 230 || target.health > health + 10
                        || enemySetup || targetVulnerable);
            case HUMMINGBIRD:
                return (dist < 320 && Math.abs(dy) < 230)
                        || (lowHealth && dist < 380)
                        || (onGround && dist > 150 && dist < 560);
            case TURKEY:
                return (dist < 230 && Math.abs(dy) < 150)
                        || (onGround && dist < 360 && Math.abs(dy) < 120)
                        || enemyActive
                        || (!onGround && dy > 35 && dist < 190);
            case PENGUIN:
                return (onGround && dist > 95 && dist < 400 && Math.abs(dy) < 150)
                        || (dy < -140 && dist < 520)
                        || enemyActive
                        || (!onGround && isVoidMap() && dist < 420 && dy < 140);
            case ROADRUNNER:
                return (onGround && dist < 330 && Math.abs(dy) < 130)
                        || (lowHealth && dist < 260)
                        || targetVulnerable
                        || (onGround && target.health > health + 12 && dist < 420);
            case SHOEBILL:
                return dist < 155
                        || (dist > 140 && dist < 330 && Math.abs(dy) < 125 && shoebillThrustReuseTimer <= 0)
                        || (onGround && dist < 220 && enemyActive && shoebillStatueReuseTimer <= 0);
            case MOCKINGBIRD:
                return (onGround && (!loungeActive || lowHealth || enemySetup))
                        || (mockingbirdCapturedType != null && dist < 330)
                        || (mockingbirdCapturedType == null
                        && dist > 60 && dist < 275 && Math.abs(dy) < 135);
            case RAZORBILL:
                return (dist < 290 && Math.abs(dy) < 150)
                        || (enemyActive && dist < 230 && razorbillCounterReuseTimer <= 0)
                        || (!onGround && dy > -120 && dist < 330);
            case GRINCHHAWK:
                return (dist < 380 && health < 120)
                        || (dist < 210 && Math.abs(dy) < 155)
                        || (onGround && grinchPresent == null && (dist > 185 || enemySetup));
            case VULTURE:
                if (isNullRockForm()) {
                    return specialCooldown <= 0 && dist < 1900.0;
                }
                return (vultureCrowTicks > 0 && ownedVultureCrowCount() < 7 && (dist < 430 || lowHealth))
                        || (vultureBait == null && vultureDownReuseTimer <= 0 && (dist > 170 || lowHealth))
                        || (dist < 320 && vultureSideReuseTimer <= 0 && targetVulnerable);
            case ROOSTER: {
                return shouldRoosterAIUseSpecial(target, dist, lowHealth, dy);
            }
            case OPIUMBIRD:
                return (dist < 340 && Math.abs(dy) < 210)
                        || (onGround && opiumResourceMeter < OPIUM_RESOURCE_MAX * 0.45)
                        || enemySetup;
            case HEISENBIRD:
                return (dist < 350 && Math.abs(dy) < 220)
                        || (onGround && opiumResourceMeter < OPIUM_RESOURCE_MAX * 0.45)
                        || enemySetup;
            case TITMOUSE:
                return shouldTitmouseAIUseSpecial(target, dist, onGround, enemySetup);
            case BAT:
                return dist < 360 && (Math.abs(dy) < 220 || !onGround || targetVulnerable);
            case PELICAN:
                return pelicanDownCharging
                        || (pelicanCargoCount <= 0 && onGround && dist > 240 && dist < 560 && !enemyActive)
                        || (pelicanCargoCount <= 0 && dist < 235 && Math.abs(dy) < 165)
                        || (pelicanCargoCount > 0 && dist < 430 && Math.abs(dy) < 210)
                        || (!onGround && dy > -150 && dist < 330);
            case RAVEN:
                return dist < 460 && (lowHealth || Math.abs(dy) < 225 || enemySetup || targetVulnerable);
            case GOOSE:
                return (dist < 370 && Math.abs(dy) < 175)
                        || (onGround && gooseNestReuseTimer <= 0 && (lowHealth || enemyActive || enemySetup))
                        || (!onGround && dy < -85.0 && !gooseLiftUsed);
            case KIWI:
                return (dist < 350 && Math.abs(dy) < 190)
                        || (!onGround && ((dy < -80.0 && !kiwiSpringUsed) || (dy > 90.0 && kiwiStompReuseTimer <= 0)));
            default:
                return dist < ideal + own.burstRange() * 0.20;
        }
    }

    private boolean hasLimitedFlight() {
        return type == BirdGame3.BirdType.PIGEON
                || type == BirdGame3.BirdType.TURKEY
                || type == BirdGame3.BirdType.GOOSE
                || type == BirdGame3.BirdType.GRINCHHAWK
                || type == BirdGame3.BirdType.PELICAN
                || type == BirdGame3.BirdType.ROOSTER;
    }

    private boolean roadrunnerSandstormActive() {
        return RoadrunnerSpecials.sandstormActive(this);
    }

    private double currentFlyUpForce() {
        if (roadrunnerSandstormActive()) {
            return ROADRUNNER_SANDSTORM_FLY_LIFT;
        }
        if (type == BirdGame3.BirdType.PELICAN) {
            return type.flyUpForce * (1.0 - pelicanEffectiveCargo() * 0.18);
        }
        return type.flyUpForce;
    }

    private boolean photoEagleSkinActive() {
        return type == BirdGame3.BirdType.EAGLE && isPhotoEagleSkin;
    }

    private static Image loadPhotoEagleImage(String resourcePath) {
        try {
            var url = Bird.class.getResource(resourcePath);
            if (url == null) {
                return null;
            }
            Image image = new Image(url.toExternalForm(), false);
            return image.isError() ? null : image;
        } catch (Exception ignored) {
            return null;
        }
    }

    private static Image photoEagleIdleImage() {
        if (photoEagleIdleSprite == null) {
            photoEagleIdleSprite = loadPhotoEagleImage("/eagle.png");
        }
        return photoEagleIdleSprite;
    }

