    private static Image firstAvailableImage(Image... images) {
        for (Image image : images) {
            if (image != null) {
                return image;
            }
        }
        return null;
    }

    private Image currentPhotoEagleSprite() {
        if (!photoEagleSkinActive()) {
            return null;
        }
        BirdAnimationState state = currentBirdAnimationState();
        return switch (state) {
            case ATTACK -> firstAvailableImage(photoEagleAttackImage(), photoEagleFlapImage(), photoEagleIdleImage());
            case FLAP, FALL, DODGE, HITSTUN -> firstAvailableImage(photoEagleFlapImage(), photoEagleAttackImage(), photoEagleIdleImage());
            case SHIELD, IDLE, KO -> firstAvailableImage(photoEagleIdleImage(), photoEagleFlapImage(), photoEagleAttackImage());
        };
    }

    private Image currentPhotoTurkeySprite() {
        if (!photoTurkeySkinActive()) {
            return null;
        }
        BirdAnimationState state = currentPhotoTurkeyAnimationState();
        return switch (state) {
            case ATTACK -> firstAvailableImage(photoTurkeyAttackImage(), photoTurkeyFlapImage(), photoTurkeyIdleImage());
            case FLAP, FALL, DODGE, HITSTUN -> firstAvailableImage(photoTurkeyFlapImage(), photoTurkeyAttackImage(), photoTurkeyIdleImage());
            case SHIELD, IDLE, KO -> firstAvailableImage(photoTurkeyIdleImage(), photoTurkeyAttackImage(), photoTurkeyFlapImage());
        };
    }

    private BirdAnimationState currentPhotoTurkeyAnimationState() {
        if (health <= 0) {
            return BirdAnimationState.KO;
        }
        if (suppressSelectEffects) {
            return BirdAnimationState.IDLE;
        }
        if (game.isMatchIntroLocked()) {
            return BirdAnimationState.IDLE;
        }
        if (stunTime > 0.0 || knockdownTimer > 0) {
            return BirdAnimationState.HITSTUN;
        }
        if (isDodging()) {
            return BirdAnimationState.DODGE;
        }
        if (isBlocking || shieldStunFrames > 0 || parryWindowFrames > 0) {
            return BirdAnimationState.SHIELD;
        }
        if (attackAnimationTimer > 0 || isGroundPounding || turkeyGobbleCharging
                || turkeyGobbleTimer > 0 || turkeyStampedeTimer > 0
                || turkeyHarvestTribunalTimer > 0) {
            return BirdAnimationState.ATTACK;
        }
        if (!isOnGround() || turkeyPanicFlapTimer > 0) {
            return vy > 1.2 && turkeyPanicFlapTimer <= 0 ? BirdAnimationState.FALL : BirdAnimationState.FLAP;
        }
        return BirdAnimationState.IDLE;
    }

    private void drawEagleGroundShadow(GraphicsContext g, double drawSize, BirdAnimationState state) {
        if (type != BirdGame3.BirdType.EAGLE || suppressSelectEffects) {
            return;
        }
        double s = sizeMultiplier;
        double speed = Math.min(1.0, Math.hypot(vx, vy) / 20.0);
        double airborneFade = isOnGround() ? 1.0 : 0.52;
        double width = drawSize * (switch (state) {
            case ATTACK, DODGE -> 1.04 + speed * 0.18;
            case FLAP, FALL -> 0.84;
            case HITSTUN -> 0.92;
            default -> 0.96;
        });
        double height = drawSize * (switch (state) {
            case ATTACK, DODGE -> 0.22;
            case FLAP, FALL -> 0.16;
            default -> 0.20;
        });
        double centerX = x + drawSize * 0.5 - vx * 0.55;
        double centerY = y + drawSize + 9.0 * s;

        g.save();
        g.setFill(Color.rgb(0, 0, 0, 0.18 * airborneFade));
        g.fillOval(centerX - width * 0.5, centerY - height * 0.5, width, height);
        g.setFill(Color.rgb(0, 0, 0, 0.08 * airborneFade));
        g.fillOval(centerX - width * 0.34, centerY - height * 0.32, width * 0.68, height * 0.64);
        g.restore();
    }

    private double photoEagleStateRotation(BirdAnimationState state) {
        double dir = facingRight ? 1.0 : -1.0;
        return switch (state) {
            case ATTACK -> dir * (7.0 + Math.min(10.0, Math.abs(vx) * 0.38));
            case FLAP -> -15.0 - Math.min(9.0, Math.max(0.0, -vy) * 0.85);
            case FALL -> 12.0 + Math.min(10.0, Math.max(0.0, vy) * 0.45);
            case HITSTUN -> -dir * (18.0 + Math.min(12.0, Math.hypot(vx, vy) * 0.55));
            case DODGE -> dir * 14.0;
            case SHIELD -> -dir * 4.0;
            case KO -> 24.0;
            case IDLE -> dir * Math.sin(System.currentTimeMillis() / 360.0) * 1.8;
        };
    }

    private double photoEagleStateScaleX(BirdAnimationState state) {
        return switch (state) {
            case ATTACK -> 1.16;
            case FLAP -> 1.08;
            case FALL -> 0.96;
            case HITSTUN -> 0.90;
            case SHIELD -> 0.88;
            case DODGE -> 1.18;
            case KO -> 0.92;
            case IDLE -> 1.0;
        };
    }

    private double photoEagleStateScaleY(BirdAnimationState state) {
        double idleBreath = 1.0 + Math.sin(System.currentTimeMillis() / 420.0) * 0.018;
        double landingSquash = landingLagTimer > 0 ? Math.max(0.84, 1.0 - landingLagTimer * 0.018) : 1.0;
        return switch (state) {
            case ATTACK -> 0.92;
            case FLAP -> 1.12;
            case FALL -> 1.04;
            case HITSTUN -> 1.08;
            case SHIELD -> 0.92;
            case DODGE -> 0.82;
            case KO -> 0.86;
            case IDLE -> idleBreath * landingSquash;
        };
    }

    private double photoEagleStateCenterYOffset(BirdAnimationState state) {
        double s = sizeMultiplier;
        return switch (state) {
            case ATTACK -> -2.0 * s;
            case FLAP -> -7.0 * s;
            case FALL -> 4.0 * s;
            case HITSTUN -> -3.0 * s;
            case SHIELD -> 5.0 * s;
            case DODGE -> 7.0 * s;
            case KO -> 14.0 * s;
            case IDLE -> 4.0 * s + Math.sin(System.currentTimeMillis() / 420.0) * 1.8 * s;
        };
    }

    private void drawPhotoEagleStateFx(GraphicsContext g, double drawSize, BirdAnimationState state) {
        if (suppressSelectEffects || visualAuditBodyOnly) {
            return;
        }
        double s = sizeMultiplier;
        double cx = x + drawSize * 0.5;
        double cy = y + drawSize * 0.5;
        double dir = facingRight ? 1.0 : -1.0;

        g.save();
        g.setLineCap(StrokeLineCap.ROUND);
        if (state == BirdAnimationState.FLAP) {
            double pulse = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 48.0);
            g.setStroke(Color.web("#E3F2FD", 0.18 + pulse * 0.16));
            g.setLineWidth(4.0 * s);
            for (int i = 0; i < 3; i++) {
                double wingW = (86.0 + i * 22.0 + pulse * 18.0) * s;
                double wingH = (42.0 + i * 11.0) * s;
                g.strokeArc(cx - dir * (22.0 + i * 6.0) * s - wingW * 0.5,
                        cy - (44.0 + i * 10.0) * s,
                        wingW,
                        wingH,
                        facingRight ? 205.0 : -25.0,
                        facingRight ? 118.0 : -118.0,
                        ArcType.OPEN);
            }
        } else if (state == BirdAnimationState.ATTACK) {
            g.setStroke(Color.web("#FFF59D", 0.34));
            g.setLineWidth(5.0 * s);
            for (int i = 0; i < 3; i++) {
                double startX = cx - dir * (46.0 + i * 18.0) * s;
                double startY = cy + (-20.0 + i * 18.0) * s;
                g.strokeLine(startX, startY, startX + dir * (106.0 + i * 14.0) * s, startY - (16.0 - i * 4.0) * s);
            }
        } else if (state == BirdAnimationState.HITSTUN) {
            g.setStroke(Color.web("#EF5350", 0.42));
            g.setLineWidth(4.0 * s);
            double recoilDir = vx == 0.0 ? -dir : -Math.signum(vx);
            for (int i = 0; i < 4; i++) {
                double yLane = cy + (-28.0 + i * 18.0) * s;
                g.strokeLine(cx - recoilDir * (18.0 + i * 8.0) * s, yLane,
                        cx - recoilDir * (80.0 + i * 18.0) * s, yLane + (i - 1.5) * 5.0 * s);
            }
        }
        g.restore();
    }

    private void drawTurkeyGroundShadow(GraphicsContext g, double drawSize, BirdAnimationState state) {
        if (type != BirdGame3.BirdType.TURKEY || !photoTurkeySkinActive() || suppressSelectEffects) {
            return;
        }
        double s = sizeMultiplier;
        double airborneFade = isOnGround() ? 1.0 : 0.50;
        double width = drawSize * (switch (state) {
            case ATTACK -> 1.18;
            case DODGE -> 1.10;
            case FLAP, FALL -> 0.82;
            case HITSTUN -> 0.96;
            default -> 1.02;
        });
        double height = drawSize * (switch (state) {
            case ATTACK, DODGE -> 0.24;
            case FLAP, FALL -> 0.17;
            default -> 0.21;
        });
        double centerX = x + drawSize * 0.5 - vx * 0.35;
        double centerY = y + drawSize + 12.0 * s;

        g.save();
        g.setFill(Color.rgb(0, 0, 0, 0.20 * airborneFade));
        g.fillOval(centerX - width * 0.5, centerY - height * 0.5, width, height);
        g.setFill(Color.rgb(0, 0, 0, 0.08 * airborneFade));
        g.fillOval(centerX - width * 0.32, centerY - height * 0.28, width * 0.64, height * 0.56);
        g.restore();
    }

    private double photoTurkeyStateRotation(BirdAnimationState state) {
        double dir = facingRight ? 1.0 : -1.0;
        return switch (state) {
            case ATTACK -> turkeyStampedeTimer > 0 ? dir * 9.0 : -dir * 6.0;
            case FLAP -> -8.0 - Math.min(8.0, Math.max(0.0, -vy) * 0.48);
            case FALL -> 10.0 + Math.min(8.0, Math.max(0.0, vy) * 0.38);
            case HITSTUN -> -dir * (12.0 + Math.min(10.0, Math.hypot(vx, vy) * 0.40));
            case DODGE -> dir * 10.0;
            case SHIELD -> -dir * 3.0;
            case KO -> 18.0;
            case IDLE -> dir * Math.sin(System.currentTimeMillis() / 460.0) * 1.1;
        };
    }

    private double photoTurkeyStateScaleX(BirdAnimationState state) {
        return switch (state) {
            case ATTACK -> turkeyStampedeTimer > 0 ? 1.22 : 1.12;
            case FLAP -> 1.06;
            case FALL -> 0.98;
            case HITSTUN -> 0.92;
            case SHIELD -> 0.90;
            case DODGE -> 1.16;
            case KO -> 0.94;
            case IDLE -> 1.0;
        };
    }

    private double photoTurkeyStateScaleY(BirdAnimationState state) {
        double idleBreath = 1.0 + Math.sin(System.currentTimeMillis() / 480.0) * 0.014;
        double landingSquash = landingLagTimer > 0 ? Math.max(0.82, 1.0 - landingLagTimer * 0.020) : 1.0;
        return switch (state) {
            case ATTACK -> turkeyStampedeTimer > 0 ? 0.86 : 0.93;
            case FLAP -> 1.10;
            case FALL -> 1.03;
            case HITSTUN -> 1.08;
            case SHIELD -> 0.91;
            case DODGE -> 0.84;
            case KO -> 0.86;
            case IDLE -> idleBreath * landingSquash;
        };
    }

    private double photoTurkeyStateCenterYOffset(BirdAnimationState state) {
        double s = sizeMultiplier;
        return switch (state) {
            case ATTACK -> turkeyStampedeTimer > 0 ? 9.0 * s : 2.0 * s;
            case FLAP -> -5.0 * s;
            case FALL -> 6.0 * s;
            case HITSTUN -> -1.0 * s;
            case SHIELD -> 7.0 * s;
            case DODGE -> 9.0 * s;
            case KO -> 15.0 * s;
            case IDLE -> 8.0 * s + Math.sin(System.currentTimeMillis() / 480.0) * 1.3 * s;
        };
    }

    private boolean photoTurkeyGroundAnchored(BirdAnimationState state) {
        return switch (state) {
            case IDLE, ATTACK, SHIELD, DODGE, HITSTUN -> true;
            case FLAP, FALL, KO -> false;
        };
    }

    private double photoTurkeyBottomTransparentRatio(Image sprite) {
        if (sprite == photoTurkeyAttackImage()) {
            return 31.0 / 360.0;
        }
        if (sprite == photoTurkeyFlapImage()) {
            return 45.0 / 500.0;
        }
        return 18.0 / 536.0;
    }

    private double photoTurkeyGroundedCenterY(Image sprite, double renderHeight, double scaleY) {
        double visibleBottomInset = renderHeight * photoTurkeyBottomTransparentRatio(sprite);
        double visibleHalfHeight = (renderHeight * 0.5 - visibleBottomInset) * Math.max(0.01, scaleY);
        double groundY = bodyBottomY() + 1.0 * sizeMultiplier;
        return groundY - visibleHalfHeight;
    }

    private void drawPhotoTurkeyStateFx(GraphicsContext g, double drawSize, BirdAnimationState state) {
        if (suppressSelectEffects || visualAuditBodyOnly) {
            return;
        }
        double s = sizeMultiplier;
        double cx = x + drawSize * 0.5;
        double cy = y + drawSize * 0.58;
        double dir = facingRight ? 1.0 : -1.0;

        g.save();
        g.setLineCap(StrokeLineCap.ROUND);
        if (state == BirdAnimationState.FLAP) {
            double pulse = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 62.0);
            g.setStroke(Color.web("#F5F5F5", 0.17 + pulse * 0.15));
            g.setLineWidth(5.0 * s);
            for (int i = 0; i < 3; i++) {
                double arcW = (88.0 + i * 24.0 + pulse * 14.0) * s;
                double arcH = (36.0 + i * 12.0) * s;
                g.strokeArc(cx - dir * (18.0 + i * 4.0) * s - arcW * 0.5,
                        cy - (38.0 + i * 10.0) * s,
                        arcW,
                        arcH,
                        facingRight ? 198.0 : -18.0,
                        facingRight ? 126.0 : -126.0,
                        ArcType.OPEN);
            }
        } else if (state == BirdAnimationState.ATTACK) {
            Color slash = turkeyStampedeTimer > 0 ? Color.web("#D7CCC8", 0.38) : Color.web("#FFCC80", 0.36);
            g.setStroke(slash);
            g.setLineWidth((turkeyStampedeTimer > 0 ? 8.0 : 5.0) * s);
            for (int i = 0; i < 3; i++) {
                double laneY = cy + (-18.0 + i * 17.0) * s;
                double reach = (82.0 + i * 18.0) * s;
                g.strokeLine(cx - dir * (42.0 + i * 8.0) * s, laneY,
                        cx + dir * reach, laneY + (i - 1.0) * 4.0 * s);
            }
        } else if (state == BirdAnimationState.HITSTUN) {
            g.setStroke(Color.web("#EF5350", 0.36));
            g.setLineWidth(4.0 * s);
            double recoilDir = vx == 0.0 ? -dir : -Math.signum(vx);
            for (int i = 0; i < 3; i++) {
                double yLane = cy + (-22.0 + i * 20.0) * s;
                g.strokeLine(cx - recoilDir * 20.0 * s, yLane,
                        cx - recoilDir * (78.0 + i * 16.0) * s, yLane + (i - 1.0) * 6.0 * s);
            }
        }
        g.restore();
    }

    private boolean drawPhotoEagleSprite(GraphicsContext g, double drawSize, AttackVisualPose pose) {
        Image sprite = currentPhotoEagleSprite();
        if (sprite == null) {
            return false;
        }
        BirdAnimationState state = currentBirdAnimationState();

        double maxWidth = drawSize * 1.9;
        double maxHeight = drawSize * 1.65;
        double aspect = sprite.getWidth() > 0 && sprite.getHeight() > 0
                ? sprite.getWidth() / sprite.getHeight()
                : 1.0;
        double renderWidth = maxWidth;
        double renderHeight = renderWidth / aspect;
        if (renderHeight > maxHeight) {
            renderHeight = maxHeight;
            renderWidth = renderHeight * aspect;
        }

        double renderCenterX = x + drawSize / 2.0;
        double renderCenterY = y + drawSize / 2.0 + photoEagleStateCenterYOffset(state);
        double rotation = (pose == null ? 0.0 : pose.spriteRotationDegrees()) + photoEagleStateRotation(state);
        double scaleX = (pose == null ? 1.0 : pose.spriteScaleX()) * photoEagleStateScaleX(state);
        double scaleY = (pose == null ? 1.0 : pose.spriteScaleY()) * photoEagleStateScaleY(state);

        drawPhotoEagleStateFx(g, drawSize, state);

        g.save();
        g.translate(renderCenterX, renderCenterY);
        g.rotate(rotation);
        g.scale((facingRight ? 1.0 : -1.0) * scaleX, scaleY);
        if (!suppressSelectEffects && !visualAuditBodyOnly && state == BirdAnimationState.ATTACK) {
            g.save();
            g.setGlobalAlpha(0.28);
            g.drawImage(sprite, -renderWidth / 2.0 - 18.0 * sizeMultiplier, -renderHeight / 2.0,
                    renderWidth, renderHeight);
            g.setGlobalAlpha(0.14);
            g.drawImage(sprite, -renderWidth / 2.0 - 34.0 * sizeMultiplier, -renderHeight / 2.0 + 3.0 * sizeMultiplier,
                    renderWidth, renderHeight);
            g.restore();
        }
        g.drawImage(sprite, -renderWidth / 2.0, -renderHeight / 2.0, renderWidth, renderHeight);
        g.restore();
        return true;
    }

    private boolean drawPhotoTurkeySprite(GraphicsContext g, double drawSize, AttackVisualPose pose) {
        Image sprite = currentPhotoTurkeySprite();
        if (sprite == null) {
            return false;
        }
        BirdAnimationState state = currentPhotoTurkeyAnimationState();

        double maxWidth = drawSize * 1.95;
        double maxHeight = drawSize * 1.92;
        double aspect = sprite.getWidth() > 0 && sprite.getHeight() > 0
                ? sprite.getWidth() / sprite.getHeight()
                : 1.0;
        double renderWidth = maxWidth;
        double renderHeight = renderWidth / aspect;
        if (renderHeight > maxHeight) {
            renderHeight = maxHeight;
            renderWidth = renderHeight * aspect;
        }

        double rotation = (pose == null ? 0.0 : pose.spriteRotationDegrees()) + photoTurkeyStateRotation(state);
        double scaleX = (pose == null ? 1.0 : pose.spriteScaleX()) * photoTurkeyStateScaleX(state);
        double scaleY = (pose == null ? 1.0 : pose.spriteScaleY()) * photoTurkeyStateScaleY(state);
        double renderCenterX = x + drawSize / 2.0;
        double renderCenterY = photoTurkeyGroundAnchored(state)
                ? photoTurkeyGroundedCenterY(sprite, renderHeight, scaleY)
                : y + drawSize / 2.0 + photoTurkeyStateCenterYOffset(state);
        boolean spriteFacesRight = sprite != photoTurkeyFlapImage();
        double orientationScale = facingRight == spriteFacesRight ? 1.0 : -1.0;

        drawPhotoTurkeyStateFx(g, drawSize, state);

        g.save();
        g.translate(renderCenterX, renderCenterY);
        g.rotate(rotation);
        g.scale(orientationScale * scaleX, scaleY);
        if (!suppressSelectEffects && !visualAuditBodyOnly && state == BirdAnimationState.ATTACK) {
            g.save();
            g.setGlobalAlpha(turkeyStampedeTimer > 0 ? 0.26 : 0.18);
            g.drawImage(sprite, -renderWidth / 2.0 - 16.0 * sizeMultiplier, -renderHeight / 2.0,
                    renderWidth, renderHeight);
            g.setGlobalAlpha(turkeyStampedeTimer > 0 ? 0.12 : 0.08);
            g.drawImage(sprite, -renderWidth / 2.0 - 32.0 * sizeMultiplier, -renderHeight / 2.0 + 4.0 * sizeMultiplier,
                    renderWidth, renderHeight);
            g.restore();
        }
        g.drawImage(sprite, -renderWidth / 2.0, -renderHeight / 2.0, renderWidth, renderHeight);
        g.restore();
        return true;
    }

    public void update(double gameSpeed) {
        try {
            if (health > 0 && game.isAI[playerIndex] && !respawnReturnActive()) aiControl();

        // === UPDATE TIMERS ===
        updateTimers(gameSpeed);
        applyPendingSmashLaunch();

        if (health <= 0) {
            updateDefeatedState(gameSpeed);
            return;
        }
        if (handleRespawnReturn(gameSpeed)) {
            return;
        }
        ensureRoosterStartingChicks();

        // === VINE GRAPPLE ===
        handleVineGrapple();

        // === RESET EXPIRED BUFFS ===
        resetExpiredBuffs();
        handleHummingbirdNectarCoating();
        handleTurkeyStuffedEffect();
        handleOpiumStatusEffects();
        handleRoadrunnerSlipEffect();

        loungeHeal();
        if (type == BirdGame3.BirdType.MOCKINGBIRD && loungeActive && loungeHealth > 0) {
            game.loungeTime[playerIndex]++;
        }

        // === OPIUM / HEISENBIRD ===
        handleOpiumBirdEffects(gameSpeed);

        boolean stunned = stunTime > 0;
        boolean airborne = !isOnGround();
        boolean leftHeld = leftPressed();
        boolean rightHeld = rightPressed();
        boolean jumpHeld = jumpPressed();
        boolean specialHeld = specialPressed();
        boolean grabHeld = grabPressed();
        boolean blockHeld = blockPressed();
        boolean reserveJumpForSpecial = !stunned && shouldReserveJumpForSpecial();
        boolean jumpJustPressed = jumpHeld && !jumpHeldLastFrame && !reserveJumpForSpecial;
        if (jumpBufferFrames > 0) jumpBufferFrames--;
        // Jump pressed together with special is a special-move combo, not a jump intent.
        if (jumpJustPressed && !specialHeld) jumpBufferFrames = JUMP_BUFFER_FRAMES;
        if (!airborne) {
            coyoteFrames = COYOTE_FRAMES;
        } else if (coyoteFrames > 0) {
            coyoteFrames--;
        }
        boolean grabJustPressed = grabHeld && !grabHeldLastFrame;
        boolean leftJustPressed = leftHeld && !leftHeldLastFrame;
        boolean rightJustPressed = rightHeld && !rightHeldLastFrame;
        boolean downHeld = !stunned && blockHeld;
        boolean inDockWater = isInDockWater();
        boolean inWindNow = isInWindVent(x, y);
        boolean inUpdraft = inWindNow || thermalTimer > 0;
        boolean reserveBlockForSpecial = !stunned
                && (shouldReserveBlockForSpecial() || shouldReserveBlockForShoebillStatueHold());
        boolean reserveBlockForAttack = !stunned && shouldReserveBlockForAttack(airborne);
        boolean defensiveBlockHeld = blockHeld && !reserveBlockForAttack && !reserveBlockForSpecial;
        boolean blockJustPressed = defensiveBlockHeld && !blockHeldLastFrame;

        if (type == BirdGame3.BirdType.PIGEON && (isOnGround() || ledgeHanging || batHanging || onVine || inDockWater)) {
            pigeonUpSpecialUsed = false;
        }
        if (isRaptor() && isOnGround()) {
            raptorUpSpecialUsed = false;
        }
        if (type == BirdGame3.BirdType.PHOENIX && isOnGround()) {
            phoenixSpiralUsed = false;
        }
        if (type == BirdGame3.BirdType.HUMMINGBIRD && isOnGround()) {
            hummingHoverBurstUsed = false;
        }
        if (type == BirdGame3.BirdType.TURKEY && isOnGround()) {
            turkeyPanicFlapUsed = false;
        }
        if (type == BirdGame3.BirdType.ROOSTER && isOnGround()) {
            roosterUpSpecialUsed = false;
        }
        if (type == BirdGame3.BirdType.ROADRUNNER && isOnGround()) {
            roadrunnerDustDevilUsed = false;
        }
        if (type == BirdGame3.BirdType.PENGUIN && isOnGround()) {
            penguinUpSpecialUsed = false;
        }
        if (type == BirdGame3.BirdType.SHOEBILL && isOnGround()) {
            shoebillUpSpecialUsed = false;
        }
        if (type == BirdGame3.BirdType.MOCKINGBIRD && isOnGround()) {
            mockingbirdUpSpecialUsed = false;
        }
        if (type == BirdGame3.BirdType.RAZORBILL && isOnGround()) {
            razorbillUpSpecialUsed = false;
        }
        if (type == BirdGame3.BirdType.GRINCHHAWK && isOnGround() && !grinchSleighRiding) {
            grinchUpSpecialUsed = false;
        }
        if (type == BirdGame3.BirdType.VULTURE && isOnGround()) {
            vultureUpSpecialUsed = false;
        }
        if (type == BirdGame3.BirdType.TITMOUSE && isOnGround()) {
            titmouseVaultUsed = false;
        }
        if (type == BirdGame3.BirdType.BAT && isOnGround()) {
            batMoonriseUsed = false;
        }
        if (type == BirdGame3.BirdType.PELICAN && isOnGround()) {
            pelicanUpSpecialUsed = false;
        }
        if (type == BirdGame3.BirdType.RAVEN && isOnGround()) {
            ravenLiftUsed = false;
        }
        if (type == BirdGame3.BirdType.GOOSE && isOnGround()) {
            gooseLiftUsed = false;
        }
        if (type == BirdGame3.BirdType.KIWI && isOnGround()) {
            kiwiSpringUsed = false;
        }
        if (isOpiumEchoPair() && isOnGround()) {
            opiumUpSpecialUsed = false;
        }

        if (airborne && landingLagTimer > 0) {
            landingLagTimer = 0;
        }
        if (airborne && knockdownTimer > 0) {
            clearKnockdownState();
        }
        if (jumpSquatTimer > 0 && (stunned || airborne || inDockWater || grabbedBy != null || ledgeHanging || batHanging || onVine || isGrappling)) {
            clearJumpSquat();
        }
        if (blockJustPressed && stunTime > 0.0) {
            techBufferTimer = TECH_INPUT_BUFFER_FRAMES;
        }

        if (stunned) {
            cancelAttackCharge();
            attackHeldLastFrame = attackPressed();
            PigeonSpecials.reset(this);
            RaptorSpecials.reset(this);
            resetHummingbirdSpecialState(false);
            resetTurkeySpecialState(false);
            resetPenguinSpecialState(false);
            resetRazorbillSpecialState();
            resetGrinchhawkSpecialState(false);
            resetVultureSpecialState(false);
            resetTitmouseSpecialState(false);
            resetBatSpecialState(false);
            resetPelicanSpecialState(false);
            resetOpiumSpecialState();
            resetGooseSpecialState(false);
            KiwiSpecials.reset(this);
        }

        if (handleGrabbedState()) {
            rememberFrameInputs(jumpHeld, specialHeld, blockHeld, grabHeld, leftHeld, rightHeld);
            if (tauntTimer > 0) tauntTimer--;
            return;
        }
        if (handleHoldingGrabState(stunned, inDockWater)) {
            rememberFrameInputs(jumpHeld, specialHeld, blockHeld, grabHeld, leftHeld, rightHeld);
            if (tauntTimer > 0) tauntTimer--;
            return;
        }

        if (type == BirdGame3.BirdType.BAT && handleBatHanging(stunned)) {
            rememberFrameInputs(jumpHeld, specialHeld, blockHeld, grabHeld, leftHeld, rightHeld);
            handleTaunts();
            if (tauntTimer > 0) tauntTimer--;
            return;
        }
        if (handleLedgeHanging(stunned)) {
            rememberFrameInputs(jumpHeld, specialHeld, blockHeld, grabHeld, leftHeld, rightHeld);
            handleTaunts();
            if (tauntTimer > 0) tauntTimer--;
            return;
        }

        handleDodgeInput(stunned, airborne, inDockWater, blockJustPressed, grabJustPressed,
                leftHeld, rightHeld, leftJustPressed, rightJustPressed);
        updateShieldState(stunned, airborne, defensiveBlockHeld, inDockWater, gameSpeed);
        if (isDodging()) {
            downHeld = false;
        }

        // === GRAVITY ===
        double gravityScale = 1.0;
        if (type == BirdGame3.BirdType.BAT && !isOnGround()) {
            gravityScale = 0.66;
        }
        if (inDockWater) {
            gravityScale *= DOCK_WATER_GRAVITY_SCALE;
        }
        vy += BirdGame3.GRAVITY * gravityScale * gameSpeed;
        if (airborne && downHeld && !inDockWater) {
            double accel = inUpdraft ? FAST_FALL_UPDRAFT_ACCEL : FAST_FALL_ACCEL;
            vy += accel * gameSpeed;
            if (!inUpdraft && vy > FAST_FALL_MAX) vy = FAST_FALL_MAX;
        }
        if (inDockWater) {
            applyDockWaterPhysics(stunned, downHeld, gameSpeed);
        }

        // === EAGLE PASSIVE ===
        handleEaglePassive(airborne);

        // === VULTURE FLYING ===
        if (type == BirdGame3.BirdType.VULTURE && !stunned && jumpPressed() && !inDockWater) {
            isFlying = true;
            vy -= 0.65;
            if (vy < -6.0) vy = -6.0;
        } else if (type == BirdGame3.BirdType.VULTURE) {
            isFlying = false;
            if (vy < 0) vy += 0.3;
        }

        // === FLY/GLIDE ===
        if (!stunned && jumpPressed() && airborne && !inDockWater
                && !(type == BirdGame3.BirdType.PIGEON && pigeonFlutterTimer > 0)
                && !(isRaptor() && raptorClimbTimer > 0)) {
            double flyLift = currentFlyUpForce();
            boolean limitedFlight = hasLimitedFlight();
            boolean thermalActive = thermalTimer > 0;
            double speedRatio = baseSpeedMultiplier > 0 ? speedMultiplier / baseSpeedMultiplier : 1.0;
            double flightLiftScale = Math.clamp(1.0 + (speedRatio - 1.0) * 0.55, 0.8, 1.45);
            double topOverflow = topCameraOverflow();
            boolean aboveCameraReach = topOverflow > 0.0;
            // Thermal Rise should always remain effective even if limited-flight fuel is drained.
            if ((!limitedFlight || limitedFlightFuel > 0 || thermalActive) && (flyLift > 0.0 || thermalLift > 0.0)) {
                if (!aboveCameraReach) {
                    vy -= (flyLift + thermalLift) * hoverRegenMultiplier * flightLiftScale;
                } else {
                    vy += (0.65 + Math.min(4.8, topOverflow * 0.045)) * gameSpeed;
                }
                double limitedFlightCap = type == BirdGame3.BirdType.ROOSTER ? -12.4 : -6.4;
                double limitedFlightThermalCap = type == BirdGame3.BirdType.ROOSTER ? -14.2 : -9.2;
                if (limitedFlight && !thermalActive) {
                    double fuelDrain = gameSpeed;
                    if (type == BirdGame3.BirdType.PELICAN) {
                        fuelDrain *= 1.0 + pelicanEffectiveCargo() * 0.35;
                    }
                    limitedFlightFuel = Math.max(0, limitedFlightFuel - fuelDrain);
                    if (vy < limitedFlightCap && !aboveCameraReach) vy = limitedFlightCap;
                } else if (limitedFlight) {
                    if (vy < limitedFlightThermalCap && !aboveCameraReach) vy = limitedFlightThermalCap;
                }
            }
            if (type == BirdGame3.BirdType.BAT && !aboveCameraReach) {
                // Bat gets stronger sustained lift so it can truly dogfight in the air.
                vy -= 0.55 * flightLiftScale;
                if (vy < -11.5) vy = -11.5;
            }
            if (type == BirdGame3.BirdType.PHOENIX) {
                if (phoenixRebornActive && !aboveCameraReach) {
                    vy -= 0.4 * flightLiftScale;
                    if (vy < -11.5) vy = -11.5;
                } else if (!aboveCameraReach && vy < -8.5) {
                    vy = -8.5;
                }
            }
        }

        if (hasLimitedFlight() && isOnGround()) {
            limitedFlightFuel = LIMITED_FLIGHT_MAX;
        }

        // === THERMAL SOARING ===
        if (thermalTimer > 0 && vy > 0 && !inDockWater) {
            vy *= 0.85;
        }

        // === HORIZONTAL MOVEMENT & JUMPING ===
        handleHorizontalMovement(stunned, airborne, jumpHeld, jumpJustPressed, gameSpeed);

        // === AIR/GROUND FRICTION ===
        if (!leftPressed() && !rightPressed()) {
            if (type == BirdGame3.BirdType.ROADRUNNER && roadrunnerBeepBurstTimer > 0) {
                roadrunnerMomentumFxTimer = Math.max(roadrunnerMomentumFxTimer, 16);
            } else if (type == BirdGame3.BirdType.ROADRUNNER && !airborne && Math.abs(vx) > 10.0) {
                vx *= 0.96;
                roadrunnerMomentumFxTimer = Math.max(roadrunnerMomentumFxTimer, 16);
            } else if (game.isFrostbiteFjordActive() && !airborne) {
                vx *= type == BirdGame3.BirdType.PENGUIN ? 0.91 : 0.94;
                if (Math.abs(vx) > 2.0 && game.nextParticleRandom() < 0.42) {
                    game.particles.add(new Particle(
                            x + 40 * sizeMultiplier - Math.signum(vx) * 22 * sizeMultiplier,
                            y + 76 * sizeMultiplier,
                            -Math.signum(vx) * (0.5 + game.nextParticleRandom() * 1.2),
                            -0.7 - game.nextParticleRandom() * 1.5,
                            Color.web("#E1F5FE", 0.66)
                    ));
                }
            } else {
                vx *= airborne ? 0.96 : 0.80;
            }
        }
        if (neonRushTimer > 0) {
            int dir = facingRight ? 1 : -1;
            vx += dir * 0.7;
            if (Math.abs(vx) > 28) vx = Math.signum(vx) * 28;
        }
        PigeonSpecials.handleState(this);
        PhoenixSpecials.handleState(this);
        RaptorSpecials.handleState(this);
        handleHummingbirdSpecialState();
        handleTurkeySpecialState();
        handlePenguinSpecialState(specialHeld);
        handleShoebillSpecialState();
        handleGrinchhawkSpecialState(jumpJustPressed, gameSpeed);
        handleVultureSpecialState(specialHeld);
        handleTitmouseSpecialState();
        handlePelicanSpecialState();
        handleBatSpecialState();
        handleRavenSpecialState(specialHeld);
        handleOpiumSpecialState();
        GooseSpecials.handleState(this, specialHeld);
        KiwiSpecials.handleState(this);

        // === RAZORBILL SPECIALS ===
        handleRazorbillSpecials();

        // === APPLY VELOCITY ===
        applyNullRockVoidRecoveryVelocity();
        double prevX = x;
        double prevY = y;
        x += vx;
        y += vy;
        if (grabbedTarget != null) {
            syncGrabbedTargetPosition();
        }
        game.resolveFrostbiteSnowbankCollision(this, prevX, prevY);

        // === THERMALS & WIND VENTS ===
        handleThermals(downHeld, prevX, prevY);
        applyPenguinDashDamage();
        handlePenguinSpecialObjects();
        handleHummingbirdNectarTraps();
        handleTurkeyFeastTraps();
        handleTitmouseSeedStashes();
        handleOpiumTraps();
        handlePhoenixAfterburn();
        emitRoadrunnerDust();
        handleRoadrunnerSandstorm();
        handleRoadrunnerSpecials(specialHeld);
        handleRoadrunnerPaintedRoads();
        handleBatPostMoveSpecialState();
        handleRavenPostMoveSpecialState();
        GooseSpecials.handlePostMoveState(this);
        KiwiSpecials.handlePostMoveState(this);
        if (tryGrabUniversalLedge(prevX, inDockWater)) {
            rememberFrameInputs(jumpHeld, specialHeld, blockHeld, grabHeld, leftHeld, rightHeld);
            handleTaunts();
            if (tauntTimer > 0) tauntTimer--;
            return;
        }

        // Penguin ice-trail after jump dash.
        if (penguinIceFxTimer > 0) {
            for (int i = 0; i < 2; i++) {
                game.particles.add(new Particle(
                        x + 40 + (game.nextParticleRandom() - 0.5) * 48,
                        y + 62 + (game.nextParticleRandom() - 0.5) * 30,
                        -vx * 0.08 + (game.nextParticleRandom() - 0.5) * 2.0,
                        -1.5 - game.nextParticleRandom() * 3.5,
                        Color.web("#B3E5FC").deriveColor(0, 1, 1, 0.75)
                ));
            }
        }

        // === BOUNDARIES ===
        handleBoundaries(gameSpeed, airborne, prevX, prevY);

        // === EAGLE DIVE / ASCENT DAMAGE ===
        handleEagleDiveImpact();

        // === VULTURE FEAST ===
        handleVultureFeast();

        // === POWER-UP PICKUP ===
        handlePowerUpPickup();

        // === TAUNTS ===
        handleTaunts();

            if (tauntTimer > 0) tauntTimer--;
            rememberFrameInputs(jumpHeld, specialHeld, blockHeld, grabHeld, leftHeld, rightHeld);
        } finally {
            updateAnimationState(gameSpeed);
            updateDisplayPose(gameSpeed);
        }
    }

    private void updateDefeatedState(double gameSpeed) {
        onDefeated();

        vy += BirdGame3.GRAVITY * gameSpeed;
        if (vy > FAST_FALL_MAX) vy = FAST_FALL_MAX;

        x += vx;
        y += vy;
        vx *= 0.94;

        double leftBound = 50;
        double rightBound = BirdGame3.WORLD_WIDTH - 150 * sizeMultiplier;
        if (usesIslandBounds()) {
            double battlefieldLeft = game.battlefieldLeftBound();
            double battlefieldRight = game.battlefieldRightBound();
            leftBound = battlefieldLeft + 50;
            rightBound = battlefieldRight - 150 * sizeMultiplier;
        }

        if (x < leftBound) {
            x = leftBound;
            vx = Math.max(0, vx);
        }
        if (x > rightBound) {
            x = rightBound;
            vx = Math.min(0, vx);
        }
        if (y < BirdGame3.CEILING_Y) {
            y = BirdGame3.CEILING_Y;
            vy = Math.max(vy, 0);
        }

        handleVerticalCollision(false);
        if (y > BirdGame3.WORLD_HEIGHT + 400) {
            y = BirdGame3.WORLD_HEIGHT + 400;
            vx = 0;
            vy = 0;
        }
    }

