    private boolean isDodging() {
        return dodgeType != DodgeType.NONE && dodgeTimer > 0;
    }

    private BirdAnimationState currentBirdAnimationState() {
        if (health <= 0) {
            return BirdAnimationState.KO;
        }
        if (suppressSelectEffects) {
            return BirdAnimationState.IDLE;
        }
        if (game.isMatchIntroLocked()) {
            return BirdAnimationState.IDLE;
        }
        if (stunTime > 0.0 || knockdownTimer > 0) {
            return BirdAnimationState.HITSTUN;
        }
        if (isDodging()) {
            return BirdAnimationState.DODGE;
        }
        if (isBlocking || shieldStunFrames > 0 || parryWindowFrames > 0) {
            return BirdAnimationState.SHIELD;
        }
        if (isGroundAttackPending() || isChargingAttack() || attackAnimationTimer > 0
                || raptorRushTimer > 0 || eagleDiveActive || diveTimer > 0 || eagleSkySovereignDiving
                || gooseHonkTimer > 0 || gooseBargeTimer > 0 || gooseNestGuardTimer > 0
                || gooseNestCounterTimer > 0 || gooseUltimateTimer > 0
                || (type == BirdGame3.BirdType.KIWI && KiwiSpecials.active(this))) {
            return BirdAnimationState.ATTACK;
        }
        if (!isOnGround()) {
            if (vy < -1.2 || raptorClimbTimer > 0 || eagleAscentActive || gooseLiftTimer > 0) {
                return BirdAnimationState.FLAP;
            }
            return BirdAnimationState.FALL;
        }
        return BirdAnimationState.IDLE;
    }

    /** Configures a disposable preview bird for the visual-audit renderer. */
    void prepareVisualAuditPose(VisualAuditPose pose) {
        health = STARTING_HEALTH;
        stunTime = 0.0;
        knockdownTimer = 0;
        isBlocking = false;
        shieldStunFrames = 0;
        parryWindowFrames = 0;
        attackAnimationTimer = 0;
        activeAttackVariant = NormalAttackVariant.NEUTRAL;
        dodgeType = DodgeType.NONE;
        dodgeTimer = 0;
        vx = 0.0;
        vy = 0.0;
        suppressSelectEffects = false;
        facingRight = true;
        y = BirdGame3.GROUND_Y - bodyHeight();

        switch (pose) {
            case IDLE -> {
            }
            case RUN -> vx = Math.max(3.0, type.speed);
            case FLAP -> {
                y -= 240.0;
                vy = -5.0;
            }
            case ATTACK -> {
                activeAttackVariant = NormalAttackVariant.SIDE_TILT;
                attackAnimationTimer = 8;
            }
            case HIT -> stunTime = 14.0;
            case KO -> health = 0.0;
        }
        prevX = x;
        prevY = y;
    }

    /** Exercises the real climb/fall animation branches without adding presentation-only audit poses. */
    void prepareVisualAuditVerticalMotion(double verticalVelocity) {
        prepareVisualAuditPose(VisualAuditPose.FLAP);
        vy = verticalVelocity;
    }

