    private void removeOwnedSummons() {
        game.crowMinions.removeIf(crow -> crow.owner == this);
        game.chickMinions.removeIf(chick -> chick.owner == this);
        game.mockingbirdShadowMinions.removeIf(shadow -> shadow.owner == this);
    }

