    private AttackVisualPose currentPigeonSpecialPose() {
        double dir = facingRight ? 1.0 : -1.0;
        if (pigeonFlutterTimer > 0) {
            double phase = pigeonSpecialPhase(pigeonFlutterTimer,
                    pigeonFlutterUltimate ? PIGEON_FLUTTER_ULTIMATE_FRAMES : PIGEON_FLUTTER_FRAMES);
            return new AttackVisualPose(
                    dir * (1.5 + 1.5 * phase),
                    -10.0 - 12.0 * phase,
                    dir * (5.0 + 3.0 * phase),
                    normalizeAngleRadians(-Math.PI / 2.0 + dir * 0.12),
                    14.0 * phase,
                    -18.0 - 5.0 * phase,
                    12.0 * phase,
                    1.08 + 0.04 * phase,
                    -30.0 - 8.0 * phase,
                    0.98,
                    1.12 + 0.08 * phase
            );
        }
        if (pigeonRushTimer > 0) {
            double phase = pigeonSpecialPhase(pigeonRushTimer,
                    pigeonRushGrounded ? PIGEON_RUSH_GROUND_FRAMES : PIGEON_RUSH_AIR_FRAMES);
            return new AttackVisualPose(
                    dir * (10.0 + 7.0 * phase),
                    pigeonRushGrounded ? -2.0 - 2.0 * phase : -6.0 - 5.0 * phase,
                    dir * (8.0 + 4.0 * phase),
                    facingRight ? -0.14 : Math.PI + 0.14,
                    16.0 + 6.0 * phase,
                    -5.0 * phase,
                    18.0 + 8.0 * phase,
                    0.80,
                    dir * (8.0 + 4.0 * phase),
                    1.18 + 0.12 * phase,
                    0.92
            );
        }
        if (pigeonScavengeTimer > 0) {
            double phase = pigeonSpecialPhase(pigeonScavengeTimer,
                    pigeonScavengeAirborne ? PIGEON_SCAVENGE_AIR_FRAMES : PIGEON_SCAVENGE_GROUND_FRAMES);
            if (pigeonScavengeAirborne) {
                return new AttackVisualPose(
                        dir * 2.0,
                        8.0 + 10.0 * phase,
                        dir * (3.0 + 2.0 * phase),
                        normalizeAngleRadians(Math.PI / 2.0 - dir * 0.10),
                        9.0 * phase,
                        10.0 * phase,
                        8.0 * phase,
                        0.82,
                        20.0 + 10.0 * phase,
                        1.01,
                        0.88
                );
            }
            double digPulse = 0.5 + 0.5 * Math.sin((PIGEON_SCAVENGE_GROUND_FRAMES - pigeonScavengeTimer) * 0.55);
            return new AttackVisualPose(
                    dir * (1.5 + 1.5 * phase),
                    8.0 + digPulse * 5.0,
                    dir * (4.0 + 2.0 * phase),
                    normalizeAngleRadians(Math.PI / 2.0 - dir * 0.34),
                    12.0 * phase,
                    8.0 + digPulse * 4.0,
                    9.0 * phase,
                    0.72,
                    dir * (5.0 + 3.0 * phase),
                    1.08 + 0.04 * phase,
                    0.82
            );
        }

        double phase = pigeonSpecialPhase(pigeonFeatherBurstTimer, PIGEON_NEUTRAL_BURST_FRAMES);
        return new AttackVisualPose(
                dir * (5.0 + 3.0 * phase),
                -1.5 * phase,
                dir * (3.0 + 2.0 * phase),
                facingRight ? 0.0 : Math.PI,
                10.0 + 6.0 * phase,
                -2.0 * phase,
                11.0 + 5.0 * phase,
                1.10,
                dir * (3.0 + 2.0 * phase),
                1.05 + 0.04 * phase,
                0.98
        );
    }

    private AttackVisualPose currentRaptorSpecialPose() {
        double dir = facingRight ? 1.0 : -1.0;
        boolean eagle = type == BirdGame3.BirdType.EAGLE;
        if (falconTerminalVelocityActive) {
            double phase = falconTerminalVelocityStriking
                    ? raptorSpecialPhase(falconTerminalVelocityTimer, FALCON_TERMINAL_VELOCITY_STRIKE_FRAMES)
                    : 0.0;
            double angle = Math.atan2(
                    falconTerminalVelocityEndY - falconTerminalVelocityStartY,
                    falconTerminalVelocityEndX - falconTerminalVelocityStartX
            );
            return new AttackVisualPose(
                    dir * (8.0 + 10.0 * phase),
                    -7.0 + 12.0 * phase,
                    dir * (18.0 + 14.0 * phase),
                    normalizeAngleRadians(angle),
                    18.0 + 10.0 * phase,
                    4.0 + 8.0 * phase,
                    15.0 + 10.0 * phase,
                    0.72,
                    18.0 + 16.0 * phase,
                    1.10 + 0.10 * phase,
                    0.84
            );
        }
        if (eagleDiveActive || eagleAscentActive) {
            if (eagleAscentActive) {
                double phase = raptorSpecialPhase(eagleAscentFrames, 36);
                return new AttackVisualPose(
                        dir * (3.0 + 2.0 * phase),
                        -14.0 - 10.0 * phase,
                        dir * (6.0 + 4.0 * phase),
                        normalizeAngleRadians(-Math.PI / 2.0 + dir * 0.08),
                        14.0 + 7.0 * phase,
                        -18.0 - 6.0 * phase,
                        12.0 + 7.0 * phase,
                        1.0,
                        -18.0 - 10.0 * phase,
                        0.98,
                        1.10 + 0.05 * phase
                );
            }
            if (eagleDiveCountdown > 0) {
                boolean diveUltimate = eagle ? diveTimer > EAGLE_DIVE_FRAMES : diveTimer > FALCON_DIVE_FRAMES;
                int startupFrames = eagle
                        ? (diveUltimate ? EAGLE_DIVE_GROUND_ULTIMATE_STARTUP_FRAMES : EAGLE_DIVE_GROUND_STARTUP_FRAMES)
                        : (diveUltimate ? FALCON_DIVE_GROUND_ULTIMATE_STARTUP_FRAMES : FALCON_DIVE_GROUND_STARTUP_FRAMES);
                double phase = raptorSpecialPhase(eagleDiveCountdown, startupFrames);
                return new AttackVisualPose(
                        dir * (2.0 + 2.0 * phase),
                        -9.0 - 11.0 * phase,
                        dir * (4.0 + 3.0 * phase),
                        normalizeAngleRadians(-Math.PI / 2.0 + dir * (eagle ? 0.10 : 0.18)),
                        12.0 + 5.0 * phase,
                        -12.0 - 4.0 * phase,
                        10.0 + 5.0 * phase,
                        0.92,
                        -12.0 - 8.0 * phase,
                        0.98,
                        1.08 + 0.04 * phase
                );
            }
            double phase = raptorSpecialPhase(diveTimer, eagle ? EAGLE_DIVE_ULTIMATE_FRAMES : FALCON_DIVE_ULTIMATE_FRAMES);
            if (!eagle) {
                return new AttackVisualPose(
                        dir * (10.0 + 8.0 * phase),
                        4.0 + 12.0 * phase,
                        dir * (18.0 + 10.0 * phase),
                        normalizeAngleRadians(Math.PI / 2.0 - dir * (Math.PI / 4.0)),
                        18.0 + 10.0 * phase,
                        8.0 + 7.0 * phase,
                        15.0 + 9.0 * phase,
                        0.76,
                        22.0 + 14.0 * phase,
                        1.08 + 0.08 * phase,
                        0.86
                );
            }
            return new AttackVisualPose(
                    dir * (9.0 + 7.0 * phase),
                    6.0 + 16.0 * phase,
                    dir * (8.0 + 5.0 * phase),
                    normalizeAngleRadians(Math.PI / 2.0 - dir * 0.16),
                    16.0 + 8.0 * phase,
                    11.0 + 8.0 * phase,
                    14.0 + 9.0 * phase,
                    0.74,
                    18.0 + 12.0 * phase,
                    1.06 + 0.08 * phase,
                    0.84
            );
        }
        if (raptorClimbTimer > 0) {
            double phase = raptorSpecialPhase(raptorClimbTimer,
                    eagle
                            ? (raptorClimbUltimate ? EAGLE_CLIMB_ULTIMATE_FRAMES : EAGLE_CLIMB_FRAMES)
                            : (raptorClimbUltimate ? FALCON_CLIMB_ULTIMATE_FRAMES : FALCON_CLIMB_FRAMES));
            return new AttackVisualPose(
                    dir * (2.0 + 2.0 * phase),
                    -12.0 - 13.0 * phase,
                    dir * (4.0 + 3.0 * phase),
                    normalizeAngleRadians(-Math.PI / 2.0 + dir * (eagle ? 0.09 : 0.18)),
                    12.0 + 6.0 * phase,
                    -16.0 - 4.0 * phase,
                    10.0 + 6.0 * phase,
                    0.92,
                    -24.0 - 8.0 * phase,
                    0.98,
                    1.10 + 0.06 * phase
            );
        }
        if (raptorRushTimer > 0) {
            double phase = raptorSpecialPhase(raptorRushTimer,
                    eagle
                            ? (raptorRushGrounded ? EAGLE_RUSH_GROUND_FRAMES : EAGLE_RUSH_AIR_FRAMES)
                            : (raptorRushGrounded ? FALCON_RUSH_GROUND_FRAMES : FALCON_RUSH_AIR_FRAMES));
            return new AttackVisualPose(
                    dir * (12.0 + 8.0 * phase),
                    eagle ? -4.0 - 2.0 * phase : -7.0 - 5.0 * phase,
                    dir * (8.0 + 5.0 * phase),
                    facingRight ? -0.18 : Math.PI + 0.18,
                    18.0 + 7.0 * phase,
                    -4.0 * phase,
                    16.0 + 9.0 * phase,
                    0.78,
                    dir * (10.0 + 5.0 * phase),
                    1.15 + 0.08 * phase,
                    0.90
            );
        }

        double phase = raptorSpecialPhase(raptorCryTimer,
                eagle
                        ? (raptorCryUltimate ? EAGLE_CRY_ULTIMATE_FRAMES : EAGLE_CRY_FRAMES)
                        : (raptorCryUltimate ? FALCON_CRY_ULTIMATE_FRAMES : FALCON_CRY_FRAMES));
        return new AttackVisualPose(
                dir * (4.0 + 3.0 * phase),
                -3.0 - 2.0 * phase,
                dir * (4.0 + 2.0 * phase),
                facingRight ? 0.0 : Math.PI,
                12.0 + 6.0 * phase,
                -4.0 - 3.0 * phase,
                12.0 + 6.0 * phase,
                1.14 + 0.08 * phase,
                dir * (4.0 + 3.0 * phase),
                1.04 + 0.03 * phase,
                1.0
        );
    }

    private AttackVisualPose currentPhoenixSpecialPose() {
        double dir = facingRight ? 1.0 : -1.0;
        if (phoenixCharging) {
            double phase = Math.clamp(phoenixChargeTimer / (double) PHOENIX_CHARGE_MAX_FRAMES, 0.0, 1.0);
            double risePulse = Math.sin(phase * Math.PI * 6.0) * (1.0 - phase) * 2.0;
            return new AttackVisualPose(
                    dir * (1.0 + 2.0 * phase),
                    -14.0 - 24.0 * phase + risePulse,
                    dir * (5.0 + 5.0 * phase),
                    normalizeAngleRadians(-Math.PI / 2.0 + dir * 0.06),
                    14.0 + 12.0 * phase,
                    -24.0 - 16.0 * phase,
                    12.0 + 10.0 * phase,
                    1.08 + 0.12 * phase,
                    -18.0 - 22.0 * phase,
                    0.96,
                    1.14 + 0.12 * phase
            );
        }
        if (phoenixBurstFxTimer > 0) {
            double fade = Math.clamp(phoenixBurstFxTimer / (double) PHOENIX_BURST_FX_FRAMES, 0.0, 1.0);
            double recoil = Math.sin(fade * Math.PI) * 5.0;
            return new AttackVisualPose(
                    -dir * recoil,
                    -6.0 * fade,
                    -dir * 5.0 * fade,
                    normalizeAngleRadians(-Math.PI / 2.0 + dir * 0.10 * fade),
                    10.0 * fade,
                    -14.0 * fade,
                    10.0 * fade,
                    1.0 + 0.08 * fade,
                    -12.0 * fade,
                    1.0,
                    1.0 + 0.06 * fade
            );
        }
        if (phoenixFireballTimer > 0) {
            boolean downwardShot = phoenixFireballVY > 0.0;
            if (phoenixCastLockTimer > 0) {
                double startupFrames = phoenixFireballUltimate
                        ? PHOENIX_FIREBALL_ULTIMATE_CAST_LOCK_FRAMES
                        : PHOENIX_FIREBALL_CAST_LOCK_FRAMES;
                double windup = 1.0 - Math.clamp(phoenixCastLockTimer / startupFrames, 0.0, 1.0);
                if (downwardShot) {
                    return new AttackVisualPose(
                            dir * (4.0 + 3.0 * windup),
                            4.0 + 5.0 * windup,
                            dir * (8.0 + 5.0 * windup),
                            normalizeAngleRadians(facingRight ? 0.58 + windup * 0.16 : Math.PI - 0.58 - windup * 0.16),
                            18.0 + 8.0 * windup,
                            5.0 + 6.0 * windup,
                            20.0 + 7.0 * windup,
                            0.94 + 0.08 * windup,
                            14.0 + 8.0 * windup,
                            1.12 + 0.06 * windup,
                            0.92
                    );
                }
                return new AttackVisualPose(
                        -dir * (5.0 + 4.0 * windup),
                        -5.0 - 4.0 * windup,
                        -dir * (8.0 + 5.0 * windup),
                        normalizeAngleRadians((facingRight ? -0.72 : Math.PI + 0.72) + dir * windup * 0.22),
                        13.0 + 7.0 * windup,
                        -12.0 - 8.0 * windup,
                        14.0 + 6.0 * windup,
                        0.96 + 0.18 * windup,
                        -dir * (7.0 + 7.0 * windup),
                        1.04,
                        0.98
                );
            }
            double phase = phoenixSpecialPhase(phoenixFireballTimer,
                    phoenixFireballUltimate ? PHOENIX_FIREBALL_ULTIMATE_FRAMES : PHOENIX_FIREBALL_FRAMES);
            if (downwardShot) {
                return new AttackVisualPose(
                        dir * (9.0 + 6.0 * phase),
                        6.0 + 4.0 * phase,
                        dir * (8.0 + 5.0 * phase),
                        normalizeAngleRadians(facingRight ? 0.50 + phase * 0.08 : Math.PI - 0.50 - phase * 0.08),
                        22.0 + 7.0 * phase,
                        6.0 + 4.0 * phase,
                        24.0 + 7.0 * phase,
                        1.14 + 0.08 * phase,
                        16.0 + 8.0 * phase,
                        1.12 + 0.08 * phase,
                        0.90
                );
            }
            return new AttackVisualPose(
                    dir * (12.0 + 8.0 * phase),
                    -4.0 - 3.0 * phase,
                    dir * (9.0 + 5.0 * phase),
                    facingRight ? -0.12 : Math.PI + 0.12,
                    20.0 + 8.0 * phase,
                    -4.0 - 2.0 * phase,
                    22.0 + 8.0 * phase,
                    1.18 + 0.08 * phase,
                    dir * (6.0 + 3.0 * phase),
                    1.14 + 0.10 * phase,
                    0.92
            );
        }
        if (phoenixSpiralTimer <= 0 && phoenixLavaTimer <= 0 && phoenixAirSideLandingFxTimer > 0) {
            double fade = Math.clamp(phoenixAirSideLandingFxTimer / (double) PHOENIX_AIR_SIDE_LANDING_FX_FRAMES, 0.0, 1.0);
            double pulse = Math.sin((1.0 - fade) * Math.PI) * 4.0;
            return new AttackVisualPose(
                    -dir * pulse,
                    8.0 + 6.0 * fade,
                    dir * (4.0 + 2.0 * fade),
                    normalizeAngleRadians(facingRight ? 0.20 : Math.PI - 0.20),
                    12.0 * fade,
                    8.0 + 4.0 * fade,
                    14.0 * fade,
                    0.96,
                    14.0 + 7.0 * fade,
                    1.08,
                    0.88
            );
        }
        if (phoenixSpiralTimer <= 0 && phoenixLavaTimer <= 0 && phoenixAirSideAimPoseTimer > 0) {
            double fade = Math.clamp(phoenixAirSideAimPoseTimer / (double) PHOENIX_AIR_SIDE_AIM_POSE_FRAMES, 0.0, 1.0);
            return new AttackVisualPose(
                    dir * (4.0 + 5.0 * fade),
                    5.0 * fade,
                    dir * (5.0 + 5.0 * fade),
                    normalizeAngleRadians(facingRight ? 0.46 + 0.06 * fade : Math.PI - 0.46 - 0.06 * fade),
                    16.0 + 5.0 * fade,
                    4.0 + 4.0 * fade,
                    18.0 + 5.0 * fade,
                    1.04 + 0.05 * fade,
                    12.0 + 5.0 * fade,
                    1.06 + 0.05 * fade,
                    0.92
            );
        }
        if (phoenixSpiralTimer > 0) {
            double phase = phoenixSpecialPhase(phoenixSpiralTimer,
                    phoenixSpiralUltimate ? PHOENIX_SPIRAL_ULTIMATE_FRAMES : PHOENIX_SPIRAL_FRAMES);
            double pulse = Math.sin(phase * Math.PI * 8.0) * 3.0;
            return new AttackVisualPose(
                    dir * (2.0 + 2.0 * phase),
                    -18.0 - 24.0 * phase + pulse,
                    dir * (10.0 + 8.0 * phase),
                    normalizeAngleRadians(-Math.PI / 2.0 + dir * 0.18),
                    18.0 + 12.0 * phase,
                    -24.0 - 12.0 * phase,
                    16.0 + 10.0 * phase,
                    0.90,
                    -30.0 - 22.0 * phase,
                    0.94,
                    1.20 + 0.12 * phase
            );
        }

        double phase = phoenixSpecialPhase(phoenixLavaTimer,
                phoenixLavaUltimate ? PHOENIX_LAVA_ULTIMATE_FRAMES : PHOENIX_LAVA_FRAMES);
        if (phoenixLavaAirborne) {
            double streamPulse = 0.5 + 0.5 * Math.sin(phase * Math.PI * 7.0);
            double holdRatio = Math.clamp(phoenixLavaHoldFrames / (double) PHOENIX_AIR_LAVA_HOLD_MAX_FRAMES, 0.0, 1.0);
            return new AttackVisualPose(
                    dir * (1.5 + streamPulse * 1.5),
                    10.0 + 8.0 * phase + holdRatio * 5.0,
                    dir * (4.0 + 4.0 * phase),
                    normalizeAngleRadians(Math.PI / 2.0 - dir * (0.08 + holdRatio * 0.05)),
                    12.0 + 7.0 * phase + holdRatio * 5.0,
                    12.0 + 8.0 * phase + holdRatio * 6.0,
                    14.0 + 8.0 * phase + holdRatio * 5.0,
                    0.82 - holdRatio * 0.04,
                    22.0 + 10.0 * phase + holdRatio * 8.0,
                    1.02,
                    0.86 - holdRatio * 0.04
            );
        }
        double crouchPulse = 0.5 + 0.5 * Math.sin(phase * Math.PI * 8.0);
        return new AttackVisualPose(
                dir * (3.0 + 2.0 * phase),
                9.0 + crouchPulse * 5.0,
                dir * (7.0 + 5.0 * phase),
                normalizeAngleRadians(Math.PI / 2.0 - dir * 0.22),
                10.0 + 6.0 * phase,
                12.0 + crouchPulse * 7.0,
                11.0 + 6.0 * phase,
                0.84,
                22.0 + crouchPulse * 8.0,
                1.06 + 0.04 * phase,
                0.84
        );
    }

